const currentTimeHHMM = () => new Date().toTimeString().slice(0, 5);
const MIN_DAILY_LINKEDIN_POSTS = 10;
const MIN_AUTOSCHEDULE_GAP_MS = 5 * 60 * 1000;

const stripHtml = (html: string) =>
  html
    .replaceAll(/<script[\s\S]*?<\/script>/gi, ' ')
    .replaceAll(/<style[\s\S]*?<\/style>/gi, ' ')
    .replaceAll(/<[^>]+>/g, ' ')
    .replaceAll(/\s+/g, ' ')
    .trim();

const defaultDashboardModulesState: DashboardModulesState = {
  moduleOrder: ['businessIdeas', 'newsWorld', 'marketTrends', 'linkedinQueue'],
  collapsed: {},
  visibility: {
    headlinesWeather: false,
    businessIdeas: true,
    newsWorld: true,
    marketTrends: true,
    linkedinQueue: true,
  },
  dailyTimes: {
    businessIdeas: '08:00',
    linkedinPosts: '09:00',
  },
  refreshIntervals: {
    worldIntelligenceHours: 4,
  },
  businessIdeas: {
    date: '',
    ideas: [],
  },
  worldIntelligence: {
    events: [],
    stories: [],
    trends: [],
    generatedAt: 0,
  },
  linkedinDrafts: {
    date: '',
    drafts: [],
  },
};

const normalizeState = (raw: Record<string, unknown>): DashboardModulesState => {
  const rawCollapsed = raw?.collapsed && typeof raw.collapsed === 'object' ? raw.collapsed : null;
  const rawVisibility =
    raw?.visibility && typeof raw.visibility === 'object' ? raw.visibility : null;
  const rawDailyTimes =
    raw?.dailyTimes && typeof raw.dailyTimes === 'object' ? raw.dailyTimes : null;
  const rawRefreshIntervals =
    raw?.refreshIntervals && typeof raw.refreshIntervals === 'object' ? raw.refreshIntervals : null;
  const rawBusinessIdeas =
    raw?.businessIdeas && typeof raw.businessIdeas === 'object' ? raw.businessIdeas : null;
  const rawWorldIntelligence =
    raw?.worldIntelligence && typeof raw.worldIntelligence === 'object'
      ? raw.worldIntelligence
      : null;
  const rawLinkedInDrafts =
    raw?.linkedinDrafts && typeof raw.linkedinDrafts === 'object' ? raw.linkedinDrafts : null;

  const supportedModules = new Set<ModuleId>([
    'headlinesWeather',
    'businessIdeas',
    'newsWorld',
    'marketTrends',
    'linkedinQueue',
  ]);

  const incomingOrder = Array.isArray(raw?.moduleOrder)
    ? raw.moduleOrder.filter((item: ModuleId) => supportedModules.has(item))
    : [];

  const mergedOrder = Array.from(
    new Set([...incomingOrder, ...defaultDashboardModulesState.moduleOrder])
  ) as ModuleId[];

  return {
    ...defaultDashboardModulesState,
    ...raw,
    moduleOrder: mergedOrder.filter((id) => id !== 'headlinesWeather'),
    collapsed: {
      ...defaultDashboardModulesState.collapsed,
      ...rawCollapsed,
    },
    visibility: {
      ...defaultDashboardModulesState.visibility,
      ...rawVisibility,
      headlinesWeather: false,
    },
    dailyTimes: {
      ...defaultDashboardModulesState.dailyTimes,
      ...rawDailyTimes,
    },
    refreshIntervals: {
      ...defaultDashboardModulesState.refreshIntervals,
      ...rawRefreshIntervals,
    },
    businessIdeas: {
      ...defaultDashboardModulesState.businessIdeas,
      ...rawBusinessIdeas,
      ideas: Array.isArray(raw?.businessIdeas?.ideas) ? raw.businessIdeas.ideas : [],
    },
    worldIntelligence: {
      ...defaultDashboardModulesState.worldIntelligence,
      ...rawWorldIntelligence,
      events: Array.isArray(raw?.worldIntelligence?.events) ? raw.worldIntelligence.events : [],
      stories: Array.isArray(raw?.worldIntelligence?.stories) ? raw.worldIntelligence.stories : [],
      trends: Array.isArray(raw?.worldIntelligence?.trends) ? raw.worldIntelligence.trends : [],
    },
    linkedinDrafts: {
      ...defaultDashboardModulesState.linkedinDrafts,
      ...rawLinkedInDrafts,
      drafts: Array.isArray(raw?.linkedinDrafts?.drafts)
        ? raw.linkedinDrafts.drafts.map((draft: LinkedInDraft) => ({
            ...draft,
            approved: draft.approved === true,
          }))
        : [],
    },
  };
};

const markerColors: Record<WorldEvent['type'], string> = {
  conflict: '#ef4444',
  political: '#f97316',
  disaster: '#eab308',
  economic: '#3b82f6',
};

const trendDirectionLabel: Record<MarketTrend['direction'], string> = {
  up: '📈 Up',
  down: '📉 Down',
  stable: '➡️ Stable',
};

const DashboardGrid: React.FC<DashboardGridProps> = ({
  userProfile,
  dashboardSettings,
  dashboardData,
  isDashboardLoading,
  onRefreshHeadlines,
  onDeepDiveIdea,
}) => {
  const [state, setState] = useState<DashboardModulesState | null>(null);
  const [draggingModule, setDraggingModule] = useState<ModuleId | null>(null);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [isGeneratingIdeas, setIsGeneratingIdeas] = useState(false);
  const [isRefreshingWorldIntel, setIsRefreshingWorldIntel] = useState(false);
  const [isGeneratingLinkedIn, setIsGeneratingLinkedIn] = useState(false);

  const [newsFilter, setNewsFilter] = useState<'all' | 'my-field' | 'global' | 'markets'>('all');
  const [selectedStory, setSelectedStory] = useState<NewsStory | null>(null);
  const [storyReader, setStoryReader] = useState<{ loading: boolean; text: string; tldr: string }>({
    loading: false,
    text: '',
    tldr: '',
  });

  const [linkedinQueue, setLinkedinQueue] = useState<LinkedInQueueItem[]>([]);
  const [linkedinHistory, setLinkedinHistory] = useState<LinkedInHistoryItem[]>([]);
  const [scheduleInputs, setScheduleInputs] = useState<Record<string, string>>({});

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<Record<string, unknown>>(null);
  const markerLayerRef = useRef<Record<string, unknown>>(null);
  const saveStateTimerRef = useRef<number | null>(null);
  const saveQueueTimerRef = useRef<number | null>(null);
  const saveHistoryTimerRef = useRef<number | null>(null);
  const ideasInFlightRef = useRef(false);
  const worldIntelInFlightRef = useRef(false);
  const linkedInInFlightRef = useRef(false);
  const queueWorkerRunningRef = useRef(false);

  const updateState = useCallback((patch: Partial<DashboardModulesState>) => {
    setState((prev) => {
      if (!prev) return prev;
      return { ...prev, ...patch };
    });
  }, []);

  useEffect(() => {
    let mounted = true;

    const load = async () => {
      logDashboardModules('load:start');
      const [loadedState, loadedQueue, loadedHistory] = await Promise.all([
        electronAPI.loadDashboardModulesState(),
        electronAPI.loadLinkedInQueue(),
        electronAPI.loadLinkedInHistory(),
      ]);

      if (!mounted) return;
      setState(normalizeState(loadedState));
      setLinkedinQueue(Array.isArray(loadedQueue) ? loadedQueue : []);
      setLinkedinHistory(Array.isArray(loadedHistory) ? loadedHistory : []);

      logDashboardModules('load:completed', {
        hasState: Boolean(loadedState),
        queueCount: Array.isArray(loadedQueue) ? loadedQueue.length : 0,
        historyCount: Array.isArray(loadedHistory) ? loadedHistory.length : 0,
      });
    };

    load().catch(console.error);
    return () => {
      mounted = false;
    };
  }, []);

  useEffect(() => {
    if (!state) return;
    if (saveStateTimerRef.current) {
      window.clearTimeout(saveStateTimerRef.current);
    }

    saveStateTimerRef.current = window.setTimeout(() => {
      electronAPI.saveDashboardModulesState(state).catch(console.error);
      saveStateTimerRef.current = null;
    }, 500);

    return () => {
      if (saveStateTimerRef.current) {
        window.clearTimeout(saveStateTimerRef.current);
        saveStateTimerRef.current = null;
      }
    };
  }, [state]);

  useEffect(() => {
    if (saveQueueTimerRef.current) {
      window.clearTimeout(saveQueueTimerRef.current);
    }

    saveQueueTimerRef.current = window.setTimeout(() => {
      electronAPI.saveLinkedInQueue(linkedinQueue).catch(console.error);
      saveQueueTimerRef.current = null;
    }, 500);

    return () => {
      if (saveQueueTimerRef.current) {
        window.clearTimeout(saveQueueTimerRef.current);
        saveQueueTimerRef.current = null;
      }
    };
  }, [linkedinQueue]);

  useEffect(() => {
    if (saveHistoryTimerRef.current) {
      window.clearTimeout(saveHistoryTimerRef.current);
    }

    saveHistoryTimerRef.current = window.setTimeout(() => {
      electronAPI.saveLinkedInHistory(linkedinHistory).catch(console.error);
      saveHistoryTimerRef.current = null;
    }, 500);

    return () => {
      if (saveHistoryTimerRef.current) {
        window.clearTimeout(saveHistoryTimerRef.current);
        saveHistoryTimerRef.current = null;
      }
    };
  }, [linkedinHistory]);

  const generateIdeas = useCallback(
    async (manual = false) => {
      if (!state) return;
      if (ideasInFlightRef.current) {
        logDashboardModules('generateIdeas:skippedAlreadyRunning', { manual });
        return;
      }

      ideasInFlightRef.current = true;
      logDashboardModules('generateIdeas:start', {
        manual,
        existingIdeas: state.businessIdeas.ideas.length,
      });
      setIsGeneratingIdeas(true);
      try {
        const apiKey = await electronAPI.getGeminiToken().catch(console.error);
        if (!apiKey) {
          throw new Error('Gemini API key is missing.');
        }

        const ideas = await generateBusinessIdeasForToday(
          apiKey,
          userProfile,
          Array.isArray(dashboardSettings?.interests) ? dashboardSettings.interests : []
        );

        logDashboardModules('generateIdeas:serviceCompleted', {
          generatedIdeas: ideas.length,
        });

        updateState({
          businessIdeas: {
            date: todayKey(),
            ideas,
          },
        });

        if (manual) {
          await electronAPI.sendNotification({
            title: 'Business Ideas Updated',
            body: `${ideas.length} fresh ideas are ready for today.`,
          }).catch(console.error);
        }
        logDashboardModules('generateIdeas:completed', { manual, generatedIdeas: ideas.length });
      } catch (error: Record<string, unknown>) {
        logger.error('Failed to generate business ideas:', error);
        logDashboardModules('generateIdeas:failed', {
          manual,
          error: String(error?.message || error),
        });
        await electronAPI.sendNotification({
          title: 'Business Ideas Generation Failed',
          body: String(error?.message || 'Unexpected error while generating business ideas.'),
        });
      } finally {
        setIsGeneratingIdeas(false);
        ideasInFlightRef.current = false;
      }
    },
    [dashboardSettings?.interests, state, updateState, userProfile]
  );

  const refreshWorldIntel = useCallback(async () => {
    if (!state) return;
    if (worldIntelInFlightRef.current) {
      logDashboardModules('refreshWorldIntel:skippedAlreadyRunning');
      return;
    }

    worldIntelInFlightRef.current = true;
    logDashboardModules('refreshWorldIntel:start', {
      existingEvents: state.worldIntelligence.events.length,
      existingStories: state.worldIntelligence.stories.length,
    });
    setIsRefreshingWorldIntel(true);
    try {
      const apiKey = await electronAPI.getGeminiToken().catch(console.error);
      if (!apiKey) {
        throw new Error('Gemini API key is missing.');
      }

      const intel = await fetchWorldIntelligence(
        apiKey,
        userProfile,
        Array.isArray(dashboardSettings?.interests) ? dashboardSettings.interests : []
      );

      updateState({
        worldIntelligence: {
          ...intel,
          generatedAt: Date.now(),
        },
      });

      logDashboardModules('refreshWorldIntel:completed', {
        events: intel.events.length,
        stories: intel.stories.length,
        trends: intel.trends.length,
      });
    } catch (error: Record<string, unknown>) {
      logger.error('Failed to refresh world intelligence:', error);
      logDashboardModules('refreshWorldIntel:failed', {
        error: String(error?.message || error),
      });
      await electronAPI.sendNotification({
        title: 'World Intelligence Refresh Failed',
        body: String(error?.message || 'Unexpected error while refreshing intelligence feeds.'),
      });
    } finally {
      setIsRefreshingWorldIntel(false);
      worldIntelInFlightRef.current = false;
    }
  }, [dashboardSettings?.interests, state, updateState, userProfile]);

  const generateLinkedIn = useCallback(
    async (manual = false) => {
      if (!state) return;
      if (linkedInInFlightRef.current) {
        logDashboardModules('generateLinkedIn:skippedAlreadyRunning', { manual });
        return;
      }

      linkedInInFlightRef.current = true;
      logDashboardModules('generateLinkedIn:start', {
        manual,
        storiesForGrounding: state.worldIntelligence.stories.length,
      });
      setIsGeneratingLinkedIn(true);
      try {
        const apiKey = await electronAPI.getGeminiToken().catch(console.error);
        if (!apiKey) {
          throw new Error('Gemini API key is missing.');
        }

        const drafts = await generateLinkedInDrafts(
          apiKey,
          userProfile,
          state.worldIntelligence.stories || []
        );

        const draftsForToday = drafts.slice(0, Math.max(MIN_DAILY_LINKEDIN_POSTS, drafts.length));

        updateState({
          linkedinDrafts: {
            date: todayKey(),
            drafts: draftsForToday,
          },
        });

        const scheduledTodayCount = linkedinQueue.filter(
          (item) => item.scheduledAt.slice(0, 10) === todayKey() && item.status === 'scheduled'
        ).length;
        const missingForDailyTarget = Math.max(0, MIN_DAILY_LINKEDIN_POSTS - scheduledTodayCount);
        let autoQueuedCount = 0;

        if (missingForDailyTarget > 0 && draftsForToday.length > 0) {
          const now = new Date();
          const start = new Date(now);
          const [targetHour, targetMinute] = state.dailyTimes.linkedinPosts.split(':').map(Number);

          if (!Number.isNaN(targetHour) && !Number.isNaN(targetMinute)) {
            start.setHours(targetHour, targetMinute, 0, 0);
          }

          if (start.getTime() <= now.getTime() + 60 * 1000) {
            start.setTime(now.getTime() + 2 * 60 * 1000);
          }

          const endOfDay = new Date(now);
          endOfDay.setHours(23, 59, 0, 0);
          const availableMs = Math.max(
            MIN_AUTOSCHEDULE_GAP_MS * missingForDailyTarget,
            endOfDay.getTime() - start.getTime()
          );
          const gapMs = Math.max(
            MIN_AUTOSCHEDULE_GAP_MS,
            Math.floor(availableMs / Math.max(1, missingForDailyTarget))
          );

          const autoItems: LinkedInQueueItem[] = [];
          for (let idx = 0; idx < missingForDailyTarget; idx += 1) {
            const draft = draftsForToday[idx % draftsForToday.length];
            if (!draft) continue;

            const publishAt = new Date(start.getTime() + idx * gapMs).toISOString();
            autoItems.push({
              id: `queue-auto-${Date.now()}-${idx}-${Math.random().toString(36).slice(2, 6)}`,
              text:
                draft.hashtags.length > 0
                  ? `${draft.text}\n\n${draft.hashtags.join(' ')}`
                  : draft.text,
              hashtags: draft.hashtags,
              engagementType: draft.engagementType,
              scheduledAt: publishAt,
              status: 'scheduled',
              createdAt: Date.now(),
            });
          }

          if (autoItems.length > 0) {
            autoQueuedCount = autoItems.length;
            setLinkedinQueue((prev) => [...autoItems, ...prev]);
            logDashboardModules('linkedinQueue:autoScheduledDailyTarget', {
              scheduledTodayCount,
              autoQueuedCount,
              target: MIN_DAILY_LINKEDIN_POSTS,
            });
          }
        }

        logDashboardModules('generateLinkedIn:serviceCompleted', {
          drafts: draftsForToday.length,
          autoQueuedCount,
        });

        if (manual) {
          await electronAPI.sendNotification({
            title: 'LinkedIn Drafts Ready',
            body:
              autoQueuedCount > 0
                ? `${draftsForToday.length} drafts ready. ${autoQueuedCount} posts auto-queued for today.`
                : `${draftsForToday.length} draft post(s) generated for review.`,
          });
        }
        logDashboardModules('generateLinkedIn:completed', {
          manual,
          drafts: draftsForToday.length,
          autoQueuedCount,
        });
      } catch (error: Record<string, unknown>) {
        logger.error('Failed to generate LinkedIn drafts:', error);
        logDashboardModules('generateLinkedIn:failed', {
          manual,
          error: String(error?.message || error),
        });
        await electronAPI.sendNotification({
          title: 'LinkedIn Draft Generation Failed',
          body: String(error?.message || 'Unexpected error while generating LinkedIn drafts.'),
        });
      } finally {
        setIsGeneratingLinkedIn(false);
        linkedInInFlightRef.current = false;
      }
    },
    [linkedinQueue, state, updateState, userProfile]
  );

  useEffect(() => {
    if (!state) return;

    const shouldGenerateIdeasNow =
      state.businessIdeas.date !== todayKey() &&
      currentTimeHHMM() >= state.dailyTimes.businessIdeas;
    if (shouldGenerateIdeasNow) {
      logDashboardModules('scheduler:triggerIdeas', {
        now: currentTimeHHMM(),
        targetTime: state.dailyTimes.businessIdeas,
      });
      generateIdeas(false).catch(console.error);
    }

    const shouldGenerateLinkedInNow =
      state.linkedinDrafts.date !== todayKey() &&
      currentTimeHHMM() >= state.dailyTimes.linkedinPosts;
    if (shouldGenerateLinkedInNow) {
      logDashboardModules('scheduler:triggerLinkedIn', {
        now: currentTimeHHMM(),
        targetTime: state.dailyTimes.linkedinPosts,
      });
      generateLinkedIn(false).catch(console.error);
    }

    const refreshEveryHours = Math.max(
      1,
      Number(state.refreshIntervals.worldIntelligenceHours || 4)
    );
    const staleMs = Date.now() - Number(state.worldIntelligence.generatedAt || 0);
    if (staleMs >= refreshEveryHours * 60 * 60 * 1000) {
      logDashboardModules('scheduler:triggerWorldIntelRefresh', {
        staleMs,
        refreshEveryHours,
      });
      refreshWorldIntel().catch(console.error);
    }

    const timer = window.setInterval(() => {
      const now = currentTimeHHMM();
      const isNewIdeaDay = state.businessIdeas.date !== todayKey();
      const isNewLinkedInDay = state.linkedinDrafts.date !== todayKey();

      if (isNewIdeaDay && now >= state.dailyTimes.businessIdeas) {
        logDashboardModules('scheduler:intervalTriggerIdeas', {
          now,
          targetTime: state.dailyTimes.businessIdeas,
        });
        generateIdeas(false).catch(console.error);
      }

      if (isNewLinkedInDay && now >= state.dailyTimes.linkedinPosts) {
        logDashboardModules('scheduler:intervalTriggerLinkedIn', {
          now,
          targetTime: state.dailyTimes.linkedinPosts,
        });
        generateLinkedIn(false).catch(console.error);
      }
    }, 60000);

    logDashboardModules('scheduler:initialized', {
      ideaTime: state.dailyTimes.businessIdeas,
      linkedInTime: state.dailyTimes.linkedinPosts,
      worldIntelHours: refreshEveryHours,
    });

    return () => window.clearInterval(timer);
  }, [state, generateIdeas, generateLinkedIn, refreshWorldIntel]);

  useEffect(() => {
    let mounted = true;

    const initMap = async () => {
      if (!mapContainerRef.current || mapRef.current) return;

      const leafletModule = await import('leaflet');
      const L = leafletModule.default;
      if (!mounted || !mapContainerRef.current) return;

      const map = L.map(mapContainerRef.current, {
        center: [20, 0],
        zoom: 2,
        zoomControl: true,
      });

      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        maxZoom: 19,
        attribution: '&copy; OpenStreetMap contributors',
      }).addTo(map);

      const markersLayer = L.layerGroup().addTo(map);
      mapRef.current = { map, L };
      markerLayerRef.current = markersLayer;
    };

    initMap().catch(console.error);

    return () => {
      mounted = false;
      if (mapRef.current?.map) {
        mapRef.current.map.remove();
        mapRef.current = null;
      }
      markerLayerRef.current = null;
    };
  }, []);

  useEffect(() => {
    if (!state || !mapRef.current || !markerLayerRef.current) return;

    const { L } = mapRef.current;
    markerLayerRef.current.clearLayers();

    state.worldIntelligence.events.forEach((event) => {
      const marker = L.circleMarker([event.lat, event.lng], {
        radius: 7,
        color: markerColors[event.type],
        weight: 2,
        fillColor: markerColors[event.type],
        fillOpacity: 0.8,
      });

      marker.bindPopup(`<strong>${event.title}</strong><br/>${event.summary}`);
      marker.on('click', () => {
        const linked = state.worldIntelligence.stories.find(
          (story) => story.url === event.sourceUrl
        );
        if (linked) {
          setSelectedStory(linked);
        }
      });

      marker.addTo(markerLayerRef.current);
    });
  }, [state]);

  const filteredStories = useMemo(() => {
    if (!state) return [];
    if (newsFilter === 'all') return state.worldIntelligence.stories;
    return state.worldIntelligence.stories.filter((story) => story.category === newsFilter);
  }, [newsFilter, state]);

  const loadStoryReader = useCallback(async (story: NewsStory) => {
    logDashboardModules('storyReader:start', {
      storyId: story.id,
      source: story.source,
      url: story.url,
    });

    setSelectedStory(story);
    setStoryReader({ loading: true, text: '', tldr: '' });

    try {
      const response = await electronAPI.httpFetch({
        method: 'GET',
        url: story.url,
      }).catch(console.error);

      const raw =
        typeof response?.data === 'string' ? response.data : JSON.stringify(response?.data || {});
      const text = stripHtml(raw).slice(0, 24000);

      const apiKey = await electronAPI.getGeminiToken().catch(console.error);
      const tldr = apiKey ? await generateArticleTldr(apiKey, text) : 'TL;DR unavailable.';

      setStoryReader({ loading: false, text, tldr });
      logDashboardModules('storyReader:completed', {
        storyId: story.id,
        textLength: text.length,
        tldrLength: tldr.length,
      });
    } catch (error) {
      logDashboardModules('storyReader:failed', {
        storyId: story.id,
        error: error instanceof Error ? error.message : String(error),
      });
      setStoryReader({
        loading: false,
        text: 'Unable to load article content from source URL.',
        tldr: 'TL;DR unavailable.',
      });
    }
  }, []);

  const updateDraftText = (draftId: string, value: string) => {
    if (!state) return;
    const updatedDrafts = state.linkedinDrafts.drafts.map((draft) =>
      draft.id === draftId ? { ...draft, text: value, charCount: value.length } : draft
    );

    updateState({
      linkedinDrafts: {
        ...state.linkedinDrafts,
        drafts: updatedDrafts,
      },
    });
  };

  const discardDraft = (draftId: string) => {
    if (!state) return;
    updateState({
      linkedinDrafts: {
        ...state.linkedinDrafts,
        drafts: state.linkedinDrafts.drafts.filter((draft) => draft.id !== draftId),
      },
    });
  };

  const addScheduledPost = (draft: LinkedInDraft) => {
    if (!draft.approved) {
      logDashboardModules('linkedinQueue:addBlocked', {
        reason: 'draft_not_approved',
        draftId: draft.id,
      });
      electronAPI.sendNotification({
        title: 'LinkedIn Queue',
        body: 'Approve this draft before scheduling it.',
      }).catch(console.error);
      return;
    }

    const scheduleAt = scheduleInputs[draft.id];
    if (!scheduleAt) {
      logDashboardModules('linkedinQueue:addBlocked', {
        reason: 'schedule_missing',
        draftId: draft.id,
      });
      return;
    }

    const scheduledAt = new Date(scheduleAt);
    if (Number.isNaN(scheduledAt.getTime())) {
      logDashboardModules('linkedinQueue:addBlocked', {
        reason: 'schedule_invalid',
        draftId: draft.id,
        scheduleAt,
      });
      return;
    }

    const queueItem: LinkedInQueueItem = {
      id: `queue-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      text: draft.hashtags.length > 0 ? `${draft.text}\n\n${draft.hashtags.join(' ')}` : draft.text,
      hashtags: draft.hashtags,
      engagementType: draft.engagementType,
      scheduledAt: scheduledAt.toISOString(),
      status: 'scheduled',
      createdAt: Date.now(),
    };

    setLinkedinQueue((prev) => [queueItem, ...prev]);
    logDashboardModules('linkedinQueue:scheduled', {
      draftId: draft.id,
      queueId: queueItem.id,
      scheduledAt: queueItem.scheduledAt,
    });
  };

  const toggleDraftApproval = (draftId: string) => {
    if (!state) return;

    updateState({
      linkedinDrafts: {
        ...state.linkedinDrafts,
        drafts: state.linkedinDrafts.drafts.map((draft) =>
          draft.id === draftId ? { ...draft, approved: !draft.approved } : draft
        ),
      },
    });
  };

  const runLinkedInAutomation = useCallback(async (item: LinkedInQueueItem) => {
    logDashboardModules('linkedinAutomation:start', {
      queueId: item.id,
      scheduledAt: item.scheduledAt,
    });

    const approval = await electronAPI.requestActionApproval({
      action: 'LinkedIn Post Automation',
      detail: `Publish scheduled post (${item.text.slice(0, 140)}...)`,
      source: 'linkedin-queue',
      rawPayload: {
        scheduledAt: item.scheduledAt,
        postText: item.text,
        steps: ['Open LinkedIn', 'Paste content', 'Submit post'],
      },
    });

    if (!approval?.approved) {
      logDashboardModules('linkedinAutomation:approvalDenied', { queueId: item.id });
      return { success: false, note: 'User rejected publishing approval.' };
    }

    logDashboardModules('linkedinAutomation:approvalGranted', { queueId: item.id });

    try {
      await electronAPI.openSystemItem({ target: 'https://www.linkedin.com/feed/' }).catch(console.error);
      await new Promise((resolve) => setTimeout(resolve, 7000));
      await electronAPI.keyboardType({ text: item.text, pressEnter: false }).catch(console.error);
      await new Promise((resolve) => setTimeout(resolve, 800));
      await electronAPI.keyboardPress({ key: 'ctrl+enter' }).catch(console.error);

      await electronAPI.sendNotification({
        title: 'LinkedIn Publisher',
        body: 'Scheduled post automation executed successfully.',
      }).catch(console.error);

      logDashboardModules('linkedinAutomation:completed', { queueId: item.id });
      return { success: true };
    } catch (error: Record<string, unknown>) {
      logDashboardModules('linkedinAutomation:failed', {
        queueId: item.id,
        error: String(error?.message || error),
      });
      try {
        await electronAPI.writeClipboard({ text: item.text }).catch(console.error);
        await electronAPI.sendNotification({
          title: 'LinkedIn Publisher Fallback',
          body: 'Automation failed. Post copied to clipboard, please paste manually.',
        }).catch(console.error);
        logDashboardModules('linkedinAutomation:fallbackClipboardApplied', { queueId: item.id });
      } catch {
        // ignored
      }

      return {
        success: false,
        note: error?.message || 'Automation failed. Copied text to clipboard as fallback.',
      };
    }
  }, []);

  useEffect(() => {
    const intervalId = window.setInterval(async () => {
      if (queueWorkerRunningRef.current) {
        return;
      }

      queueWorkerRunningRef.current = true;

      try {
        const dueItems = linkedinQueue.filter(
          (item) =>
            item.status === 'scheduled' && new Date(item.scheduledAt).getTime() <= Date.now()
        );

        if (dueItems.length > 0) {
          logDashboardModules('linkedinQueue:dueItemsDetected', { dueCount: dueItems.length });
        }

        for (const item of dueItems) {
          const result = await runLinkedInAutomation(item);

          setLinkedinQueue((prev) =>
            prev.map((entry) =>
              entry.id === item.id
                ? { ...entry, status: result.success ? 'posted' : 'failed' }
                : entry
            )
          );

          setLinkedinHistory((prev) => [
            {
              id: `history-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
              text: item.text,
              scheduledAt: item.scheduledAt,
              postedAt: new Date().toISOString(),
              success: result.success,
              note: result.note,
            },
            ...prev,
          ]);

          logDashboardModules('linkedinQueue:itemProcessed', {
            queueId: item.id,
            success: result.success,
            note: result.note || '',
          });
        }
      } finally {
        queueWorkerRunningRef.current = false;
      }
    }, 20000);

    return () => window.clearInterval(intervalId);
  }, [linkedinQueue, runLinkedInAutomation]);

  const handleDragDrop = (target: ModuleId) => {
    if (!state || !draggingModule || draggingModule === target) return;

    const current = [...state.moduleOrder];
    const from = current.indexOf(draggingModule);
    const to = current.indexOf(target);
    if (from < 0 || to < 0) return;

    current.splice(from, 1);
    current.splice(to, 0, draggingModule);

    updateState({ moduleOrder: current });
    setDraggingModule(null);
  };

  const toggleCollapse = (id: ModuleId) => {
    if (!state) return;
    updateState({
      collapsed: {
        ...state.collapsed,
        [id]: !state.collapsed[id],
      },
    });
  };

  const toggleVisibility = (id: ModuleId) => {
    if (!state) return;
    updateState({
      visibility: {
        ...state.visibility,
        [id]: !state.visibility[id],
      },
    });
  };

  if (!state) {
    return (
      <div className='w-full h-full flex items-center justify-center text-j-text-secondary'>
        Loading dashboard modules...
      </div>
    );
  }

  const visibleModuleOrder = state.moduleOrder.filter(
    (moduleId) => moduleId !== 'headlinesWeather' && state.visibility[moduleId]
  );

  const renderModuleBody = (moduleId: ModuleId) => {
    if (state.collapsed[moduleId]) {
      return null;
    }

    if (moduleId === 'headlinesWeather') {
      return (
        <div className='space-y-3'>
          <div className='flex items-center justify-between'>
            <span className='text-xs text-j-text-muted'>Pinned Headlines + Weather</span>
            <button
              onClick={onRefreshHeadlines}
              className='inline-flex items-center gap-2 px-3 py-1 rounded-lg border border-white/10 text-j-text-secondary hover:text-j-cyan transition-colors'
            >
              <RefreshCw size={12} className={isDashboardLoading ? 'animate-spin' : ''} />
              Refresh
            </button>
          </div>

          {Array.isArray(dashboardData?.headlines) && dashboardData.headlines.length > 0 ? (
            <ul className='space-y-2 text-sm text-j-text-primary'>
              {dashboardData.headlines.map((headline: string, idx: number) => (
                <li key={`${headline}-${idx}`} className='border-b border-white/5 pb-2'>
                  {headline}
                </li>
              ))}
            </ul>
          ) : (
            <p className='text-sm text-j-text-muted'>No headlines yet.</p>
          )}

          <div className='grid grid-cols-1 md:grid-cols-3 gap-2'>
            <div className='rounded-xl border border-white/10 p-2 text-xs text-j-text-secondary'>
              {dashboardData?.weather?.today || 'Today weather unavailable'}
            </div>
            <div className='rounded-xl border border-white/10 p-2 text-xs text-j-text-secondary'>
              {dashboardData?.weather?.tomorrow || 'Tomorrow weather unavailable'}
            </div>
            <div className='rounded-xl border border-white/10 p-2 text-xs text-j-text-secondary'>
              {dashboardData?.weather?.dayAfter || 'Day-after weather unavailable'}
            </div>
          </div>
        </div>
      );
    }

    if (moduleId === 'businessIdeas') {
      return (
        <div className='space-y-3'>
          <div className='flex items-center justify-between'>
            <span className='text-xs text-j-text-muted'>
              Daily generation at {state.dailyTimes.businessIdeas}
            </span>
            <button
              onClick={() => generateIdeas(true)}
              className='inline-flex items-center gap-2 px-3 py-1 rounded-lg border border-white/10 text-j-text-secondary hover:text-j-cyan transition-colors'
            >
              <RefreshCw size={12} className={isGeneratingIdeas ? 'animate-spin' : ''} />
              Regenerate
            </button>
          </div>

          <div className='space-y-2 max-h-72 overflow-y-auto custom-scrollbar pr-1'>
            {state.businessIdeas.ideas.length === 0 ? (
              <p className='text-sm text-j-text-muted'>No ideas generated yet for today.</p>
            ) : (
              state.businessIdeas.ideas.map((idea) => (
                <details
                  key={idea.id}
                  className='rounded-xl border border-white/10 bg-black/20 p-3'
                >
                  <summary className='cursor-pointer text-sm font-semibold text-white'>
                    {idea.title}
                  </summary>
                  <p className='text-xs text-j-text-secondary mt-2'>{idea.summary}</p>
                  <p className='text-xs text-j-text-muted mt-2'>
                    Why relevant today: {idea.relevance}
                  </p>
                  <div className='flex items-center justify-between mt-3'>
                    <span className='text-xs text-j-cyan'>Feasibility: {idea.feasibility}/5</span>
                    <div className='flex items-center gap-2'>
                      {idea.trendLink && (
                        <a
                          href={idea.trendLink}
                          target='_blank'
                          rel='noreferrer'
                          className='text-xs text-j-text-secondary hover:text-j-cyan'
                        >
                          Trend Link
                        </a>
                      )}
                      <button
                        onClick={() => onDeepDiveIdea(idea)}
                        className='text-xs px-2 py-1 rounded-md bg-j-cyan/15 border border-j-cyan/25 text-j-cyan hover:bg-j-cyan hover:text-black transition-colors'
                      >
                        Deep Dive
                      </button>
                    </div>
                  </div>
                </details>
              ))
            )}
          </div>
        </div>
      );
    }

    if (moduleId === 'newsWorld') {
      return (
        <div className='space-y-3'>
          <div className='rounded-xl border border-white/10 bg-black/20 p-3'>
            <div className='flex items-center justify-between'>
              <span className='text-xs text-j-text-muted'>Pinned Headlines + Weather</span>
              <button
                onClick={onRefreshHeadlines}
                className='inline-flex items-center gap-2 px-3 py-1 rounded-lg border border-white/10 text-j-text-secondary hover:text-j-cyan transition-colors'
              >
                <RefreshCw size={12} className={isDashboardLoading ? 'animate-spin' : ''} />
                Refresh
              </button>
            </div>

            {Array.isArray(dashboardData?.headlines) && dashboardData.headlines.length > 0 ? (
              <ul className='space-y-1.5 text-xs text-j-text-primary mt-2'>
                {dashboardData.headlines.slice(0, 5).map((headline: string, idx: number) => (
                  <li key={`${headline}-${idx}`} className='border-b border-white/5 pb-1.5'>
                    {headline}
                  </li>
                ))}
              </ul>
            ) : (
              <p className='text-xs text-j-text-muted mt-2'>No headlines yet.</p>
            )}

            <div className='grid grid-cols-1 md:grid-cols-3 gap-2 mt-2'>
              <div className='rounded-xl border border-white/10 p-2 text-[11px] text-j-text-secondary'>
                {dashboardData?.weather?.today || 'Today weather unavailable'}
              </div>
              <div className='rounded-xl border border-white/10 p-2 text-[11px] text-j-text-secondary'>
                {dashboardData?.weather?.tomorrow || 'Tomorrow weather unavailable'}
              </div>
              <div className='rounded-xl border border-white/10 p-2 text-[11px] text-j-text-secondary'>
                {dashboardData?.weather?.dayAfter || 'Day-after weather unavailable'}
              </div>
            </div>
          </div>

          <div className='flex items-center justify-between'>
            <span className='text-xs text-j-text-muted'>Interactive World Intelligence Map</span>
            <button
              onClick={refreshWorldIntel}
              className='inline-flex items-center gap-2 px-3 py-1 rounded-lg border border-white/10 text-j-text-secondary hover:text-j-cyan transition-colors'
            >
              <RefreshCw size={12} className={isRefreshingWorldIntel ? 'animate-spin' : ''} />
              Refresh
            </button>
          </div>

          <div className='h-56 rounded-xl overflow-hidden border border-white/10'>
            <div ref={mapContainerRef} className='w-full h-full' />
          </div>

          <div className='flex items-center gap-2 flex-wrap'>
            {['all', 'my-field', 'global', 'markets'].map((filter) => (
              <button
                key={filter}
                onClick={() => setNewsFilter(filter as Record<string, unknown>)}
                className={`px-2 py-1 text-[11px] rounded-md border ${
                  newsFilter === filter
                    ? 'border-j-cyan/40 text-j-cyan bg-j-cyan/10'
                    : 'border-white/10 text-j-text-muted'
                }`}
              >
                {filter === 'my-field'
                  ? 'My Field'
                  : filter.charAt(0).toUpperCase() + filter.slice(1)}
              </button>
            ))}
          </div>

          <div className='max-h-64 overflow-y-auto custom-scrollbar space-y-2 pr-1'>
            {filteredStories.map((story) => (
              <button
                key={story.id}
                onClick={() => loadStoryReader(story)}
                className='w-full text-left rounded-xl border border-white/10 bg-black/20 p-3 hover:border-j-cyan/30 transition-colors'
              >
                <h4 className='text-sm font-semibold text-white'>{story.headline}</h4>
                <p className='text-xs text-j-text-secondary mt-1'>{story.teaser}</p>
                <div className='flex items-center justify-between text-[11px] text-j-text-muted mt-2'>
                  <span>{story.source}</span>
                  <span>{new Date(story.timestamp).toLocaleString()}</span>
                </div>
              </button>
            ))}
          </div>
        </div>
      );
    }

    if (moduleId === 'marketTrends') {
      return (
        <div className='space-y-2 max-h-72 overflow-y-auto custom-scrollbar pr-1'>
          {state.worldIntelligence.trends.length === 0 ? (
            <p className='text-sm text-j-text-muted'>No trend data yet.</p>
          ) : (
            state.worldIntelligence.trends.map((trend) => (
              <div key={trend.id} className='rounded-xl border border-white/10 bg-black/20 p-3'>
                <div className='flex items-center justify-between'>
                  <h4 className='text-sm text-white font-semibold'>{trend.name}</h4>
                  <span className='text-xs text-j-cyan'>Relevance {trend.relevanceScore}/5</span>
                </div>
                <p className='text-xs text-j-text-secondary mt-1'>{trend.explanation}</p>
                <div className='text-xs mt-2'>{trendDirectionLabel[trend.direction]}</div>
              </div>
            ))
          )}
        </div>
      );
    }

    return (
      <div className='space-y-3'>
        <div className='flex items-center justify-between'>
          <span className='text-xs text-j-text-muted'>
            Daily generation at {state.dailyTimes.linkedinPosts}
          </span>
          <button
            onClick={() => generateLinkedIn(true)}
            className='inline-flex items-center gap-2 px-3 py-1 rounded-lg border border-white/10 text-j-text-secondary hover:text-j-cyan transition-colors'
          >
            <RefreshCw size={12} className={isGeneratingLinkedIn ? 'animate-spin' : ''} />
            Generate Drafts
          </button>
        </div>

        <div className='space-y-3 max-h-64 overflow-y-auto custom-scrollbar pr-1'>
          {state.linkedinDrafts.drafts.map((draft) => (
            <div key={draft.id} className='rounded-xl border border-white/10 bg-black/20 p-3'>
              <textarea
                value={draft.text}
                onChange={(event) => updateDraftText(draft.id, event.target.value)}
                className='w-full min-h-[90px] rounded-lg bg-white/5 border border-white/10 p-2 text-xs text-j-text-primary'
              />
              <div className='flex items-center justify-between mt-2 text-[11px] text-j-text-muted'>
                <span>{draft.engagementType}</span>
                <span>{draft.charCount} chars</span>
              </div>
              <div className='text-[11px] text-j-cyan mt-1'>{draft.hashtags.join(' ')}</div>

              <div className='grid grid-cols-1 sm:grid-cols-3 gap-2 mt-2'>
                <button
                  onClick={() => toggleDraftApproval(draft.id)}
                  className={`rounded-lg border text-[11px] px-2 py-1 ${
                    draft.approved
                      ? 'border-emerald-400/40 bg-emerald-400/10 text-emerald-300'
                      : 'border-white/10 text-j-text-muted'
                  }`}
                >
                  {draft.approved ? 'Approved' : 'Approve'}
                </button>
                <input
                  type='datetime-local'
                  value={scheduleInputs[draft.id] || ''}
                  onChange={(event) =>
                    setScheduleInputs((prev) => ({ ...prev, [draft.id]: event.target.value }))
                  }
                  className='rounded-lg bg-white/5 border border-white/10 px-2 py-1 text-[11px] text-j-text-secondary'
                />
                <button
                  onClick={() => addScheduledPost(draft)}
                  className={`rounded-lg border text-[11px] px-2 py-1 ${
                    draft.approved
                      ? 'border-j-cyan/30 bg-j-cyan/10 text-j-cyan'
                      : 'border-white/10 bg-white/5 text-j-text-muted'
                  }`}
                >
                  Schedule
                </button>
                <button
                  onClick={() => discardDraft(draft.id)}
                  className='rounded-lg border border-white/10 text-j-text-muted text-[11px] px-2 py-1'
                >
                  Discard
                </button>
              </div>
            </div>
          ))}
        </div>

        <div className='border-t border-white/10 pt-3'>
          <h4 className='text-xs uppercase tracking-wider text-j-text-muted mb-2'>
            Schedule Queue
          </h4>
          <div className='max-h-28 overflow-y-auto custom-scrollbar space-y-2 pr-1'>
            {linkedinQueue.length === 0 ? (
              <p className='text-xs text-j-text-muted'>No scheduled posts yet.</p>
            ) : (
              linkedinQueue.map((entry) => (
                <div key={entry.id} className='rounded-lg border border-white/10 p-2 text-[11px]'>
                  <div className='flex justify-between gap-2'>
                    <span className='text-j-text-primary truncate'>{entry.text.slice(0, 70)}</span>
                    <span className='text-j-cyan'>{entry.status}</span>
                  </div>
                  <p className='text-j-text-muted mt-1'>
                    {new Date(entry.scheduledAt).toLocaleString()}
                  </p>
                </div>
              ))
            )}
          </div>
        </div>

        <div className='border-t border-white/10 pt-3'>
          <h4 className='text-xs uppercase tracking-wider text-j-text-muted mb-2'>Post History</h4>
          <div className='max-h-28 overflow-y-auto custom-scrollbar space-y-2 pr-1'>
            {linkedinHistory.length === 0 ? (
              <p className='text-xs text-j-text-muted'>No history yet.</p>
            ) : (
              linkedinHistory.map((entry) => (
                <div key={entry.id} className='rounded-lg border border-white/10 p-2 text-[11px]'>
                  <div className='flex justify-between'>
                    <span className='text-j-text-primary truncate'>{entry.text.slice(0, 70)}</span>
                    <span className={entry.success ? 'text-emerald-300' : 'text-rose-300'}>
                      {entry.success ? 'Posted' : 'Failed'}
                    </span>
                  </div>
                  <p className='text-j-text-muted mt-1'>
                    {new Date(entry.postedAt).toLocaleString()}
                  </p>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    );
  };

  const moduleMeta: Record<ModuleId, { title: string; icon: React.ReactNode }> = {
    headlinesWeather: {
      title: 'Headlines + Weather',
      icon: <Newspaper size={15} />,
    },
    businessIdeas: {
      title: "Today's Business Ideas",
      icon: <Lightbulb size={15} />,
    },
    newsWorld: {
      title: 'News & World Intelligence',
      icon: <Globe size={15} />,
    },
    marketTrends: {
      title: 'Market Trends Panel',
      icon: <TrendingUp size={15} />,
    },
    linkedinQueue: {
      title: 'LinkedIn Post Queue',
      icon: <Share2 size={15} />,
    },
  };

  return (
    <div className='w-full h-full overflow-y-auto custom-scrollbar pr-1 sm:pr-2 pb-2'>
      <div className='flex items-center justify-between mb-4'>
        <div>
          <h2 className='text-2xl font-bold text-white'>Modular Dashboard</h2>
          <p className='text-sm text-j-text-muted'>Drag cards to reorder, collapse when needed.</p>
        </div>

        <button
          onClick={() => setSettingsOpen((v) => !v)}
          className='inline-flex items-center gap-2 px-3 py-2 rounded-xl border border-white/10 text-sm text-j-text-secondary hover:text-j-cyan transition-colors'
        >
          <Settings size={14} />
          Dashboard Settings
        </button>
      </div>

      {settingsOpen && (
        <div className='mb-4 rounded-2xl border border-white/10 bg-black/30 p-4 grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 text-sm'>
          <div>
            <h4 className='text-sm uppercase tracking-wider text-j-text-muted mb-2'>
              Module Visibility
            </h4>
            <div className='space-y-2'>
              {(Object.keys(state.visibility) as ModuleId[]).map((id) =>
                id === 'headlinesWeather' ? null : (
                  <label key={id} className='flex items-center justify-between text-sm'>
                    <span>{moduleMeta[id].title}</span>
                    <button
                      onClick={() => toggleVisibility(id)}
                      className='text-j-cyan hover:brightness-110'
                    >
                      {state.visibility[id] ? <Eye size={14} /> : <EyeOff size={14} />}
                    </button>
                  </label>
                )
              )}
            </div>
          </div>

          <div>
            <h4 className='text-sm uppercase tracking-wider text-j-text-muted mb-2'>
              Daily Auto-Generation
            </h4>
            <div className='space-y-2'>
              <label className='text-sm flex items-center justify-between'>
                <span>Business Ideas</span>
                <input
                  type='time'
                  value={state.dailyTimes.businessIdeas}
                  onChange={(event) =>
                    updateState({
                      dailyTimes: { ...state.dailyTimes, businessIdeas: event.target.value },
                    })
                  }
                  className='bg-white/5 border border-white/10 rounded px-2 py-1 text-sm'
                />
              </label>

              <label className='text-sm flex items-center justify-between'>
                <span>LinkedIn Drafts</span>
                <input
                  type='time'
                  value={state.dailyTimes.linkedinPosts}
                  onChange={(event) =>
                    updateState({
                      dailyTimes: { ...state.dailyTimes, linkedinPosts: event.target.value },
                    })
                  }
                  className='bg-white/5 border border-white/10 rounded px-2 py-1 text-sm'
                />
              </label>
            </div>
          </div>

          <div>
            <h4 className='text-sm uppercase tracking-wider text-j-text-muted mb-2'>
              Refresh Intervals
            </h4>
            <label className='text-sm flex items-center justify-between'>
              <span>World Intel (hours)</span>
              <input
                type='number'
                min={1}
                max={24}
                value={state.refreshIntervals.worldIntelligenceHours}
                onChange={(event) =>
                  updateState({
                    refreshIntervals: {
                      ...state.refreshIntervals,
                      worldIntelligenceHours: Math.max(1, Number(event.target.value || 4)),
                    },
                  })
                }
                className='w-20 bg-white/5 border border-white/10 rounded px-2 py-1 text-sm'
              />
            </label>
          </div>
        </div>
      )}

      <div className='grid grid-cols-[repeat(auto-fit,minmax(300px,1fr))] gap-4 pb-4'>
        {visibleModuleOrder.map((moduleId) => (
          <div
            key={moduleId}
            draggable
            onDragStart={() => setDraggingModule(moduleId)}
            onDragOver={(event) => event.preventDefault()}
            onDrop={() => handleDragDrop(moduleId)}
            className='rounded-2xl border border-white/10 bg-j-panel/70 backdrop-blur-xl p-4 flex flex-col gap-3 text-sm'
          >
            <div className='flex items-center justify-between'>
              <div className='flex items-center gap-2 text-j-text-primary'>
                <span className='text-j-cyan'>{moduleMeta[moduleId].icon}</span>
                <h3 className='text-base font-semibold'>{moduleMeta[moduleId].title}</h3>
              </div>
              <div className='flex items-center gap-2'>
                <button
                  onClick={() => toggleCollapse(moduleId)}
                  className='text-j-text-muted hover:text-j-cyan transition-colors'
                >
                  {state.collapsed[moduleId] ? <ChevronDown size={14} /> : <ChevronUp size={14} />}
                </button>
                <button className='text-j-text-muted cursor-grab'>
                  <GripVertical size={14} />
                </button>
              </div>
            </div>

            {renderModuleBody(moduleId)}
          </div>
        ))}
      </div>

      {selectedStory && (
        <div className='fixed inset-0 z-[130] flex items-center justify-center p-4'>
          <button
            type='button'
            aria-label='Close story reader'
            className='absolute inset-0 bg-black/70 backdrop-blur-sm'
            onClick={() => setSelectedStory(null)}
          />
          <div className='relative z-10 w-full max-w-4xl max-h-[85vh] overflow-y-auto custom-scrollbar rounded-2xl border border-white/10 bg-j-panel p-5'>
            <div className='flex items-center justify-between mb-3'>
              <h3 className='text-lg font-bold text-white'>{selectedStory.headline}</h3>
              <button
                onClick={() => setSelectedStory(null)}
                className='text-j-text-muted hover:text-white transition-colors'
              >
                Close
              </button>
            </div>

            {storyReader.loading ? (
              <p className='text-sm text-j-text-muted'>Loading article and generating TL;DR...</p>
            ) : (
              <>
                <div className='rounded-xl border border-j-cyan/25 bg-j-cyan/5 p-3 mb-3'>
                  <h4 className='text-sm font-semibold text-j-cyan mb-1'>AI TL;DR</h4>
                  <p className='text-sm text-j-text-secondary whitespace-pre-wrap'>
                    {storyReader.tldr}
                  </p>
                </div>

                <div className='rounded-xl border border-white/10 bg-black/25 p-3'>
                  <p className='text-sm text-j-text-primary whitespace-pre-wrap leading-relaxed'>
                    {storyReader.text}
                  </p>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default DashboardGrid;

import React, { useState, useEffect, useRef } from 'react';

import { logger } from "../../lib/logger";

interface LoadingScreenProps {
  onFinished?: () => void;
}

const LoadingScreen: React.FC<LoadingScreenProps> = ({ onFinished }) => {
  const [progress, setProgress] = useState(0);
  const [activeStatus, setActiveStatus] = useState('INITIALIZING KERNEL...');
  const audioLoadingRef = useRef<HTMLAudioElement>(null);
  const audioFinishedRef = useRef<HTMLAudioElement>(null);
  const onFinishedRef = useRef<LoadingScreenProps['onFinished']>(onFinished);

  useEffect(() => {
    onFinishedRef.current = onFinished;
  }, [onFinished]);

  // Tech-heavy statuses
  const systems = [
    'BIOS_CHECK :: OK',
    'LOADING_NEURAL_NETWORKS...',
    'DECRYPTING_USER_VAULT...',
    'ESTABLISHING_SECURE_LINK...',
    'OPTIMIZING_MEMORY_SHARDS...',
    'LOADING_CORE_MODULES...',
    'SYSTEM_READY',
  ];

  useEffect(() => {
    // Attempt audio play
    if (audioLoadingRef.current) {
      audioLoadingRef.current.volume = 0.7;
      audioLoadingRef.current.play().catch(logger.error);
    }

    let currentProgress = 0;
    const interval = setInterval(() => {
      // "Heavy" loading simulation: simpler logic but feels weighty
      // Random increment between 0.5 and 2.5
      // Doubled speed: random increment between 1.0 and 5.0
      const increment = Math.random() * 4 + 1.0;
      currentProgress += increment;

      if (currentProgress >= 100) {
        currentProgress = 100;
        clearInterval(interval);
        handleCompletion();
      }

      setProgress(currentProgress);

      // Update status text based on progress chunks
      const statusIndex = Math.floor((currentProgress / 100) * (systems.length - 1));
      setActiveStatus(systems[statusIndex]);
    }, 100);

    return () => clearInterval(interval);
  }, []);

  const handleCompletion = () => {
    if (audioLoadingRef.current) {
      // Fade out loading sound
      const fadeOut = setInterval(() => {
        if (audioLoadingRef.current && audioLoadingRef.current.volume > 0.05) {
          audioLoadingRef.current.volume -= 0.05;
        } else {
          clearInterval(fadeOut);
          audioLoadingRef.current?.pause();
        }
      }, 100);
    }

    if (audioFinishedRef.current) {
      audioFinishedRef.current.volume = 0.8;
      audioFinishedRef.current.play().catch(logger.error);
    }

    setTimeout(() => {
      const finished = onFinishedRef.current;
      if (finished) finished();
    }, 750); // Reduced delay to 0.75s for faster entry
  };

  return (
    <div className='fixed inset-0 z-[9999] flex flex-col items-center justify-center bg-[#020406] text-white overflow-hidden font-mono select-none cursor-wait'>
      {/* Ambient Audio */}
      <audio ref={audioLoadingRef} loop>
        <source src='audio/loading.wav' type='audio/wav' />
      </audio>
      <audio ref={audioFinishedRef}>
        <source src='audio/access_granted.wav' type='audio/wav' />
      </audio>

      {/* Background Texture (Scanlines & Vignette) */}
      <div className='absolute inset-0 bg-scan-line opacity-20 pointer-events-none' />
      <div className='absolute inset-0 bg-radial-gradient from-transparent to-[#000000] opacity-80 pointer-events-none' />

      {/* Main Content Container */}
      <div className='relative z-10 flex flex-col items-center w-[400px]'>
        {/* Header / Logo Text */}
        <div className='mb-12 flex flex-col items-center group'>
          <img
            src='logo.png'
            alt='Theta Logo'
            className='w-24 h-24 mb-6 object-contain rounded-2xl opacity-80 group-hover:opacity-100 transition-all duration-500'
          />
          <h1
            className='text-4xl font-bold tracking-[0.3em] text-white animate-glitch'
            data-text='Theta'
          >
            Theta
          </h1>
          <div className='w-full h-[1px] bg-gradient-to-r from-transparent via-[#00E5FF] to-transparent mt-4 opacity-50 group-hover:opacity-100 transition-opacity duration-500' />
        </div>

        {/* Progress Bar Container */}
        <div className='w-full mb-2'>
          <div className='flex justify-between text-[10px] text-[#00E5FF]/60 mb-1 tracking-widest'>
            <span>SYS.LOAD</span>
            <span>{progress.toFixed(1)}%</span>
          </div>

          {/* The Bar */}
          <div className='w-full h-[2px] bg-[#111] relative overflow-hidden'>
            <div
              className='absolute top-0 left-0 h-full bg-[#00E5FF] shadow-[0_0_15px_rgba(0,229,255,0.6)] transition-all duration-100 ease-out'
              style={{ width: `${progress}%` }}
            />
          </div>
        </div>

        {/* Status Text (Typing/Flicker Effect) */}
        <div className='w-full flex justify-start h-6'>
          <span className='text-[10px] text-[#00E5FF]/80 font-mono tracking-widest uppercase animate-pulse'>
            {'>'} {activeStatus}
          </span>
        </div>
      </div>

      {/* Footer / System Info */}
      <div className='absolute bottom-10 w-full px-12 flex justify-between items-end opacity-40 text-[9px] text-[#00E5FF]/50 tracking-[0.2em] font-mono'>
        <div className='flex flex-col gap-1'>
          <span>HOST: LOCALHOST</span>
          <span>PORT: SECURE:443</span>
        </div>
        <div className='flex flex-col items-end gap-1'>
          <span>ID: 8X-992-AZ</span>
          <span>VER: 2.4.0-NIGHTLY</span>
        </div>
      </div>
    </div>
  );
};

export default LoadingScreen;

import { Plus, Trash2, Save, Search, FileText, Download } from 'lucide-react';
import { marked } from 'marked';
import Quill from 'quill';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import TurndownService from 'turndown';

import { useAudio } from '../../hooks/useAudio';

import 'quill/dist/quill.snow.css';

interface Note {
  id: string;
  title: string;
  content: string;
  tags?: string[];
  timestamp?: number;
  createdAt?: number;
  updatedAt?: number;
  date?: string;
}

interface NotesSectionProps {
  notes: Note[];
  onSaveNote: (note: Note) => void;
  onDeleteNote: (id: string) => void;
}

const NotesSection: React.FC<NotesSectionProps> = ({ notes, onSaveNote, onDeleteNote }) => {
  const [selectedNoteId, setSelectedNoteId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [titleInput, setTitleInput] = useState('');
  const [tagsInput, setTagsInput] = useState('');
  const [editorHtml, setEditorHtml] = useState('<p></p>');
  const [isDirty, setIsDirty] = useState(false);
  const [contextMenu, setContextMenu] = useState<{
    note: Note;
    x: number;
    y: number;
  } | null>(null);

  const editorContainerRef = useRef<HTMLDivElement>(null);
  const quillRef = useRef<Quill | null>(null);
  const isProgrammaticUpdateRef = useRef(false);

  const { playClick } = useAudio();

  const turndown = useMemo(
    () =>
      new TurndownService({
        codeBlockStyle: 'fenced',
        headingStyle: 'atx',
      }),
    []
  );

  const normalizedNotes: Note[] = useMemo(
    () =>
      notes.map((note) => ({
        ...note,
        tags: Array.isArray(note.tags) ? note.tags : [],
        createdAt: note.createdAt || note.timestamp || Date.now(),
        updatedAt: note.updatedAt || note.timestamp || Date.now(),
      })),
    [notes]
  );

  const selectedNote = useMemo(
    () => normalizedNotes.find((note) => note.id === selectedNoteId) || null,
    [normalizedNotes, selectedNoteId]
  );

  const handleCreateNew = () => {
    playClick();
    const newNote: Note = {
      id: Date.now().toString(),
      title: 'Untitled Note',
      content: '',
      tags: [],
      createdAt: Date.now(),
      updatedAt: Date.now(),
      timestamp: Date.now(),
    };

    onSaveNote(newNote as Record<string, unknown>);
    setSelectedNoteId(newNote.id);
    setTitleInput(newNote.title);
    setTagsInput('');
    setEditorHtml('<p></p>');
    setIsDirty(false);
  };

  const handleSelectNote = (note: Note) => {
    playClick();
    setSelectedNoteId(note.id);
    setTitleInput(note.title || 'Untitled Note');
    setTagsInput((note.tags || []).join(', '));
    setEditorHtml(marked.parse(note.content || '') as string);
    setIsDirty(false);
  };

  const handleSave = () => {
    if (!selectedNote) return;

    const markdownBody = turndown.turndown(editorHtml || '<p></p>');
    const normalizedTags = tagsInput
      .split(',')
      .map((tag) => tag.trim())
      .filter(Boolean);

    const updatedNote: Note = {
      ...selectedNote,
      title: titleInput.trim() || 'Untitled Note',
      content: markdownBody,
      tags: normalizedTags,
      updatedAt: Date.now(),
      timestamp: Date.now(),
    };

    onSaveNote(updatedNote as Record<string, unknown>);
    setIsDirty(false);
  };

  const exportNote = (note: Note, format: 'md' | 'txt') => {
    const extension = format === 'md' ? 'md' : 'txt';
    const body = format === 'md' ? note.content : note.content.replace(/[#*_`>-]/g, '');
    const safeTitle = (note.title || 'note').replace(/[^a-z0-9-_ ]/gi, '').trim() || 'note';
    const fileName = `${safeTitle}.${extension}`;

    const blob = new Blob([body], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const filteredNotes = normalizedNotes.filter((note) => {
    const query = searchQuery.toLowerCase();
    return note.title.toLowerCase().includes(query) || note.content.toLowerCase().includes(query);
  });

  useEffect(() => {
    if (!editorContainerRef.current || quillRef.current) return;

    const quill = new Quill(editorContainerRef.current, {
      theme: 'snow',
      modules: {
        toolbar: {
          container: '#notes-rich-toolbar',
          handlers: {
            divider: function () {
              const range = quill.getSelection(true);
              const index = range?.index || quill.getLength();
              quill.clipboard.dangerouslyPasteHTML(index, '<hr />');
              quill.setSelection(index + 1, 0);
            },
          },
        },
      },
    });

    quill.on('text-change', () => {
      if (isProgrammaticUpdateRef.current) return;
      setEditorHtml(quill.root.innerHTML);
      setIsDirty(true);
    });

    quillRef.current = quill;

    return () => {
      quillRef.current = null;
    };
  }, []);

  useEffect(() => {
    if (!selectedNote || !quillRef.current) return;

    isProgrammaticUpdateRef.current = true;
    quillRef.current.clipboard.dangerouslyPasteHTML(
      marked.parse(selectedNote.content || '') as string
    );
    setTimeout(() => {
      isProgrammaticUpdateRef.current = false;
    }, 0);
  }, [selectedNote?.id]);

  useEffect(() => {
    if (normalizedNotes.length === 0) return;
    if (!selectedNoteId) {
      handleSelectNote(normalizedNotes[0]);
    }
  }, [normalizedNotes, selectedNoteId]);

  useEffect(() => {
    const hideContextMenu = () => setContextMenu(null);
    window.addEventListener('click', hideContextMenu);
    return () => window.removeEventListener('click', hideContextMenu);
  }, []);

  return (
    <div className='h-full w-full flex rounded-3xl overflow-hidden border border-white/10 bg-j-panel/60 backdrop-blur-xl'>
      <aside className='w-[320px] border-r border-white/10 p-4 flex flex-col gap-4 bg-black/20'>
        <div className='flex items-center justify-between'>
          <div>
            <h2 className='text-xl font-semibold text-white'>Notes</h2>
            <p className='text-[11px] text-j-text-muted'>Rich editor + markdown storage</p>
          </div>
          <button
            onClick={handleCreateNew}
            className='p-2 rounded-xl bg-j-cyan/15 text-j-cyan border border-j-cyan/30 hover:bg-j-cyan hover:text-black transition-colors'
          >
            <Plus size={16} />
          </button>
        </div>

        <div className='relative'>
          <Search size={14} className='absolute left-3 top-3 text-j-text-muted' />
          <input
            value={searchQuery}
            onChange={(event) => setSearchQuery(event.target.value)}
            placeholder='Search title or content...'
            className='w-full rounded-xl bg-white/5 border border-white/10 pl-9 pr-3 py-2 text-xs text-j-text-primary focus:outline-none focus:border-j-cyan/40'
          />
        </div>

        <div className='flex-1 overflow-y-auto custom-scrollbar space-y-2 pr-1'>
          {filteredNotes.map((note) => (
            <button
              key={note.id}
              onClick={() => handleSelectNote(note)}
              onContextMenu={(event) => {
                event.preventDefault();
                setContextMenu({ note, x: event.clientX, y: event.clientY });
              }}
              className={`rounded-2xl border p-3 cursor-pointer transition-colors ${
                selectedNoteId === note.id
                  ? 'border-j-cyan/40 bg-j-cyan/10'
                  : 'border-white/10 bg-white/5 hover:border-white/20'
              }`}
            >
              <div className='flex items-start justify-between gap-2'>
                <h3 className='text-sm text-white font-semibold truncate'>
                  {note.title || 'Untitled Note'}
                </h3>
                <button
                  onClick={(event) => {
                    event.stopPropagation();
                    playClick();
                    onDeleteNote(note.id);
                  }}
                  className='p-1 rounded-lg hover:bg-rose-500/20 text-j-text-muted hover:text-rose-400 transition-colors'
                >
                  <Trash2 size={12} />
                </button>
              </div>
              <p className='text-[11px] text-j-text-secondary line-clamp-2 mt-1'>
                {note.content || 'No content'}
              </p>
              <div className='text-[10px] text-j-text-muted mt-2'>
                {new Date(note.updatedAt || note.timestamp || Date.now()).toLocaleString()}
              </div>
            </button>
          ))}

          {filteredNotes.length === 0 && (
            <div className='text-xs text-j-text-muted border border-white/10 rounded-xl p-4'>
              No matching notes found.
            </div>
          )}
        </div>
      </aside>

      <section className='flex-1 p-5 flex flex-col gap-4'>
        {!selectedNote ? (
          <div className='h-full flex items-center justify-center text-j-text-muted text-sm'>
            Select a note to start editing.
          </div>
        ) : (
          <>
            <div className='flex items-center justify-between gap-3'>
              <div className='flex-1 grid grid-cols-1 md:grid-cols-2 gap-3'>
                <input
                  value={titleInput}
                  onChange={(event) => {
                    setTitleInput(event.target.value);
                    setIsDirty(true);
                  }}
                  placeholder='Note title'
                  className='w-full rounded-xl bg-white/5 border border-white/10 px-3 py-2 text-sm text-j-text-primary focus:outline-none focus:border-j-cyan/40'
                />
                <input
                  value={tagsInput}
                  onChange={(event) => {
                    setTagsInput(event.target.value);
                    setIsDirty(true);
                  }}
                  placeholder='Tags (comma separated)'
                  className='w-full rounded-xl bg-white/5 border border-white/10 px-3 py-2 text-sm text-j-text-primary focus:outline-none focus:border-j-cyan/40'
                />
              </div>

              <button
                onClick={handleSave}
                className='inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-j-cyan text-black font-semibold hover:brightness-110 transition-colors'
              >
                <Save size={14} />
                {isDirty ? 'Save' : 'Saved'}
              </button>
            </div>

            <div
              id='notes-rich-toolbar'
              className='rounded-xl border text-black border-white/10 bg-black p-2'
            >
              <span className='ql-formats'>
                <select className='ql-header' defaultValue=''>
                  <option value='1'>H1</option>
                  <option value='2'>H2</option>
                  <option value='3'>H3</option>
                  <option value=''>Normal</option>
                </select>
              </span>
              <span className='ql-formats'>
                <button className='ql-bold' />
                <button className='ql-italic' />
                <button className='ql-underline' />
                <button className='ql-strike' />
              </span>
              <span className='ql-formats'>
                <button className='ql-list' value='ordered' />
                <button className='ql-list' value='bullet' />
              </span>
              <span className='ql-formats'>
                <button className='ql-blockquote' />
                <button className='ql-code-block' />
                <button className='ql-divider'>HR</button>
              </span>
              <span className='ql-formats'>
                <button className='ql-clean' />
              </span>
            </div>

            <div className='flex-1 rounded-2xl border border-white/10 overflow-hidden bg-white'>
              <div ref={editorContainerRef} className='h-full text-black' />
            </div>

            <div className='text-[11px] text-j-text-muted'>
              Notes are stored as markdown internally and rendered as rich text in editor.
            </div>
          </>
        )}
      </section>

      {contextMenu && (
        <div
          className='fixed z-[140] rounded-xl border border-white/10 bg-j-panel shadow-2xl p-1'
          style={{ left: contextMenu.x, top: contextMenu.y }}
        >
          <button
            onClick={() => exportNote(contextMenu.note, 'md')}
            className='w-full text-left px-3 py-2 text-xs text-j-text-primary hover:bg-white/5 rounded-lg inline-flex items-center gap-2'
          >
            <Download size={12} />
            Export as .md
          </button>
          <button
            onClick={() => exportNote(contextMenu.note, 'txt')}
            className='w-full text-left px-3 py-2 text-xs text-j-text-primary hover:bg-white/5 rounded-lg inline-flex items-center gap-2'
          >
            <FileText size={12} />
            Export as .txt
          </button>
        </div>
      )}
    </div>
  );
};

export default NotesSection;

import { Maximize2, Minimize2, Zap, Layers, ZoomIn, ZoomOut, RotateCcw, Move, X } from 'lucide-react';
import React, { useRef, useEffect, useState } from 'react';

import { logger } from "../../lib/logger";

interface VisualHubProps {
    isExpanded: boolean;
    onToggleExpand: () => void;
    generatedImage: string | null;
    generatedDiagram: string | null;
    isVisualizing: boolean;
    isDiagramRendering: boolean;
    onReset: () => void;
    zoom: number;
    setZoom: React.Dispatch<React.SetStateAction<number>>;
    pan: { x: number; y: number };
    setPan: React.Dispatch<React.SetStateAction<{ x: number; y: number }>>;
    isDragging: boolean;
    setIsDragging: React.Dispatch<React.SetStateAction<boolean>>;
    dragStart: { x: number; y: number };
    setDragStart: React.Dispatch<React.SetStateAction<{ x: number; y: number }>>;
}

const VisualHub: React.FC<VisualHubProps> = ({
    isExpanded,
    onToggleExpand,
    generatedImage,
    generatedDiagram,
    isVisualizing,
    isDiagramRendering,
    onReset,
    zoom,
    setZoom,
    pan,
    setPan,
    isDragging,
    setIsDragging,
    dragStart,
    setDragStart
}) => {
    const diagramRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (generatedDiagram) {
            const renderDiagram = async () => {
                try {
                    if (diagramRef.current) diagramRef.current.innerHTML = '';
                    // @ts-ignore
                    const { svg } = await window.mermaid.render('mermaid-svg-' + Date.now(), generatedDiagram);
                    if (diagramRef.current) {
                        diagramRef.current.innerHTML = svg;
                    }
                } catch (err: Record<string, unknown>) {
                    logger.error("Mermaid rendering failed:", err);
                    if (diagramRef.current) {
                        diagramRef.current.innerHTML = `<div class="p-6 border border-j-crimson/30 bg-j-crimson/5 rounded-xl text-j-crimson text-xs font-mono text-left overflow-auto max-h-full">
              <p class="font-bold mb-2 uppercase tracking-widest opacity-70">Rendering Error</p>
              <pre class="whitespace-pre-wrap">${err.message || 'Syntax Error'}</pre>
              <p class="mt-4 opacity-50 italic">AI will automatically attempt to repair the syntax.</p>
            </div>`;
                    }
                }
            };
            setTimeout(renderDiagram, 500);
        }
    }, [generatedDiagram]);

    const handleWheel = (e: React.WheelEvent) => {
        if (!generatedImage && !generatedDiagram) return;
        e.preventDefault();
        const scaleBy = 1.1;
        const newZoom = e.deltaY < 0 ? zoom * scaleBy : zoom / scaleBy;
        setZoom(Math.min(Math.max(0.1, newZoom), 5));
    };

    const handleMouseDown = (e: React.MouseEvent) => {
        if ((generatedImage || generatedDiagram) && !isVisualizing && !isDiagramRendering) {
            setIsDragging(true);
            setDragStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
        }
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        if (isDragging) {
            setPan({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
        }
    };

    const handleMouseUp = () => {
        setIsDragging(false);
    };

    const resetView = () => {
        setZoom(1);
        setPan({ x: 0, y: 0 });
    };

    return (
        <div className={`
      ${isExpanded
                ? 'fixed inset-4 z-[100] flex items-center justify-center'
                : 'hidden md:flex flex-[0.8] xl:flex-[1.0] items-start justify-center pb-6 lg:pb-12 px-4 lg:px-8'
            }
    `}>
            <div className={`
        ${isExpanded
                    ? 'w-full h-full rounded-[2.5rem] lg:rounded-[3.5rem]'
                    : 'w-full max-w-[650px] xl:max-w-[850px] h-full rounded-[2.5rem] lg:rounded-[3.5rem]'
                }
        border border-white/[0.08] bg-j-panel/95 backdrop-blur-3xl p-6 relative overflow-hidden shadow-[0_0_100px_rgba(0,0,0,0.8)] flex flex-col items-center justify-center text-center group transition-all duration-500 hover:border-j-cyan/20
      `}>
                {/* Sci-Fi Decorative Corners */}
                <div className="absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 border-j-cyan/30 rounded-tl-3xl pointer-events-none opacity-40 group-hover:opacity-100 transition-opacity" />
                <div className="absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 border-j-cyan/30 rounded-tr-3xl pointer-events-none opacity-40 group-hover:opacity-100 transition-opacity" />
                <div className="absolute bottom-0 left-0 w-8 h-8 border-b-2 border-l-2 border-j-cyan/30 rounded-bl-3xl pointer-events-none opacity-40 group-hover:opacity-100 transition-opacity" />
                <div className="absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 border-j-cyan/30 rounded-br-3xl pointer-events-none opacity-40 group-hover:opacity-100 transition-opacity" />

                {/* Background Grid Accent */}
                <div className="absolute inset-0 sci-fi-grid opacity-[0.2] pointer-events-none" />

                {/* Hub Status Indicator */}
                <div className="absolute top-6 left-6 flex items-center gap-2 px-3 py-1.5 bg-j-cyan/5 border border-j-cyan/10 rounded-lg pointer-events-none group-hover:bg-j-cyan/10 transition-all z-20">
                    <div className="w-1.5 h-1.5 bg-j-cyan rounded-full animate-ping" />
                    <span className="text-[9px] font-mono text-j-cyan font-bold tracking-[0.2em] uppercase">Visual Hub</span>
                    <div className="w-[1px] h-3 bg-j-cyan/20 mx-1" />
                    <span className="text-[8px] font-mono text-j-text-muted uppercase">Ready</span>
                </div>

                <div className="absolute top-6 right-6 flex gap-3 z-30">
                    <button
                        onClick={onToggleExpand}
                        className={`
              p-2.5 rounded-xl border transition-all duration-300 flex items-center justify-center
              ${isExpanded
                                ? 'bg-j-cyan/20 border-j-cyan/50 text-j-cyan shadow-[0_0_20px_rgba(0,229,255,0.2)]'
                                : 'bg-white/5 border-white/10 text-j-text-muted hover:text-j-cyan hover:border-j-cyan/30 hover:bg-j-cyan/5'
                            }
            `}
                        title={isExpanded ? "Minimize" : "Expand"}
                    >
                        {isExpanded ? <Minimize2 size={18} /> : <Maximize2 size={18} />}
                    </button>

                    {(generatedImage || generatedDiagram) && !isVisualizing && (
                        <button
                            onClick={onReset}
                            className="px-4 py-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-xl text-[10px] font-mono text-j-text-muted hover:text-j-crimson hover:border-j-crimson/30 transition-all h-fit self-center font-bold uppercase tracking-widest"
                        >
                            Reset Hub
                        </button>
                    )}
                </div>

                <div
                    className={`
            flex-1 w-full h-full relative overflow-hidden flex items-center justify-center
            ${(generatedImage || generatedDiagram) && !isVisualizing && !isDiagramRendering ? 'cursor-grab active:cursor-grabbing' : ''}
          `}
                    onWheel={handleWheel}
                    onMouseDown={handleMouseDown}
                    onMouseMove={handleMouseMove}
                    onMouseUp={handleMouseUp}
                    onMouseLeave={handleMouseUp}
                >
                    {/* Active Scanline Effect */}
                    {(generatedImage || generatedDiagram || isVisualizing || isDiagramRendering) && (
                        <div className="scanline" />
                    )}

                    {isVisualizing || isDiagramRendering ? (
                        <div className="flex flex-col items-center justify-center gap-6 animate-pulse">
                            <div className="relative">
                                <div className="w-24 h-24 border-b-2 border-j-cyan rounded-full animate-spin" />
                                <div className="absolute inset-0 flex items-center justify-center">
                                    <Zap size={32} className="text-j-cyan animate-pulse" />
                                </div>
                            </div>
                            <div className="flex flex-col items-center gap-2">
                                <h3 className="text-sm font-mono text-j-cyan tracking-[0.4em] uppercase font-bold text-glow">
                                    {isDiagramRendering ? 'Designing' : 'Materializing'}
                                </h3>
                                <div className="flex gap-2">
                                    {[0, 1, 2].map(i => (
                                        <div key={i} className="w-1 h-3 bg-j-cyan/50 rounded-full animate-pulse" style={{ animationDelay: `${i * 0.2}s` }} />
                                    ))}
                                </div>
                            </div>
                            <p className="text-[9px] font-mono text-j-text-muted uppercase tracking-[0.2em] max-w-[300px] opacity-60">
                                {isDiagramRendering ? 'Constructing Visual Logic...' : 'Interpreting Neural Synapses into Visual Data...'}
                            </p>
                        </div>
                    ) : generatedImage ? (
                        <div
                            className="transition-transform duration-75 ease-out will-change-transform"
                            style={{
                                transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`,
                                transformOrigin: 'center center'
                            }}
                        >
                            <img
                                src={generatedImage}
                                alt="Generated AI"
                                className="max-w-[90vw] max-h-[80vh] object-contain rounded-[2rem] shadow-2xl pointer-events-none"
                            />
                        </div>
                    ) : generatedDiagram ? (
                        <div
                            className="w-full h-full flex items-center justify-center p-8 transition-transform duration-75 ease-out will-change-transform"
                            style={{
                                transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`,
                                transformOrigin: 'center center'
                            }}
                        >
                            <div ref={diagramRef} className="mermaid-viewer w-full pointer-events-none" />
                        </div>
                    ) : (
                        <div className="flex flex-col items-center">
                            <div className="w-16 h-16 rounded-full border border-dashed border-j-text-muted/30 flex items-center justify-center mb-6 group-hover:border-j-cyan/50 group-hover:rotate-45 transition-all duration-700">
                                <Layers className="text-j-text-muted group-hover:text-j-cyan" size={32} />
                            </div>
                            <h3 className="text-xl font-mono text-j-text-primary tracking-wider mb-4 leading-relaxed font-bold uppercase">
                                Visual Intelligence Hub
                            </h3>

                            <div className="space-y-2 text-j-text-secondary font-mono text-xs max-w-sm tracking-wide">
                                <p className="opacity-80">Images, Flowcharts, and Mindmaps will materialize here.</p>
                                <p className="text-j-cyan/60 font-medium">SYSTEM READY - AWAITING DATA INPUT</p>
                            </div>
                        </div>
                    )}
                </div>

                {/* Bottom Zoom/Pan Controls */}
                {(generatedImage || generatedDiagram) && !isVisualizing && !isDiagramRendering && (
                    <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-2 px-6 py-3 bg-black/60 backdrop-blur-xl border border-white/10 rounded-2xl z-30 animate-in slide-in-from-bottom-8 duration-700 shadow-[0_20px_50px_rgba(0,0,0,0.5)]">
                        <button
                            onClick={() => setZoom(prev => Math.min(prev * 1.2, 5))}
                            className="p-2.5 bg-white/5 hover:bg-j-cyan/10 rounded-xl text-j-text-muted hover:text-j-cyan transition-all border border-transparent hover:border-j-cyan/30"
                            title="Zoom In"
                        >
                            <ZoomIn size={18} />
                        </button>
                        <div className="w-[1px] h-6 bg-white/10 mx-2" />
                        <div className="flex flex-col items-center">
                            <span className="text-[10px] font-mono text-j-cyan font-bold tracking-tighter">
                                {Math.round(zoom * 100)}%
                            </span>
                            <span className="text-[8px] font-mono text-j-text-muted uppercase tracking-widest opacity-50">Scale</span>
                        </div>
                        <div className="w-[1px] h-6 bg-white/10 mx-2" />
                        <button
                            onClick={() => setZoom(prev => Math.max(prev / 1.2, 0.1))}
                            className="p-2.5 bg-white/5 hover:bg-j-cyan/10 rounded-xl text-j-text-muted hover:text-j-cyan transition-all border border-transparent hover:border-j-cyan/30"
                            title="Zoom Out"
                        >
                            <ZoomOut size={18} />
                        </button>
                        <button
                            onClick={resetView}
                            className="p-2.5 bg-white/5 hover:bg-j-amber/10 rounded-xl text-j-text-muted hover:text-j-amber transition-all border border-transparent hover:border-j-amber/30 ml-2"
                            title="Reset View"
                        >
                            <RotateCcw size={18} />
                        </button>
                        <div className="hidden lg:flex items-center gap-2 ml-4 px-3 py-1.5 bg-j-cyan/5 rounded-lg border border-j-cyan/20">
                            <Move size={14} className="text-j-cyan animate-pulse" />
                            <span className="text-[9px] font-mono text-j-cyan/80 uppercase tracking-widest">Hold Left-Click to Pan</span>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

