import React, { createContext, use, useState, useEffect } from "react";

import { logger } from "../lib/logger";

import type { Memory, UserProfile, DashboardSettings, HistoryMessage, FolderConfig, Note, Task, Contact } from "../types/index";

const electronAPI = (window as unknown as { electronAPI: Record<string, unknown> }).electronAPI;

interface DataContextType {
  memories: Memory[];
  setMemories: React.Dispatch<React.SetStateAction<Memory[]>>;
  handleAddMemory: (input: string) => Promise<void>;
  handleDeleteMemory: (id: string) => Promise<void>;
  handleMemoriesUpdated: (updatedMemories: Memory[]) => Promise<void>;

  userProfile: UserProfile;
  setUserProfile: React.Dispatch<React.SetStateAction<UserProfile>>;
  handleUpdateProfile: (field: string, value: string) => Promise<void>;

  dashboardSettings: DashboardSettings;
  setDashboardSettings: React.Dispatch<React.SetStateAction<DashboardSettings>>;
  handleUpdateDashboardSettings: (settings: DashboardSettings) => Promise<void>;

  history: HistoryMessage[];
  setHistory: React.Dispatch<React.SetStateAction<HistoryMessage[]>>;
  historySettings: Record<string, unknown>;
  setHistorySettings: React.Dispatch<React.SetStateAction<Record<string, unknown>>>;
  handleUpdateHistorySettings: (settings: Record<string, unknown>) => Promise<void>;
  handleClearHistory: () => Promise<void>;

  importedFolders: FolderConfig[];
  setImportedFolders: React.Dispatch<React.SetStateAction<FolderConfig[]>>;
  handleImportFolder: () => Promise<void>;
  handleRemoveFolder: (idx: number) => void;
  handleOpenFolder: (folderPath: string) => Promise<void>;
  handleOpenVaultFolder: (folderName: string) => Promise<void>;

  vaultPath: string;
  setVaultPath: React.Dispatch<React.SetStateAction<string>>;

  notes: Note[];
  setNotes: React.Dispatch<React.SetStateAction<Note[]>>;
  handleSaveNote: (note: Note) => Promise<void>;
  handleDeleteNote: (id: string) => Promise<void>;

  tasks: Task[];
  setTasks: React.Dispatch<React.SetStateAction<Task[]>>;
  handleSaveTasks: (updatedTasks: Task[]) => Promise<void>;

  contacts: Contact[];
  setContacts: React.Dispatch<React.SetStateAction<Contact[]>>;
  handleAddContact: (name: string, phone: string) => Promise<void>;
  handleDeleteContact: (id: string) => Promise<void>;

  hasCheckedKey: boolean;
  setHasCheckedKey: React.Dispatch<React.SetStateAction<boolean>>;
}

const DataContext = createContext<DataContextType | undefined>(undefined);

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [memories, setMemories] = useState<Memory[]>([]);
  const [userProfile, setUserProfile] = useState<UserProfile>({ name: "", location: "", profession: "", bio: "" });
  const [dashboardSettings, setDashboardSettings] = useState<DashboardSettings>({ interests: ["Tech", "Pakistan", "Global Economy"], refreshInterval: 3600 });
  const [history, setHistory] = useState<HistoryMessage[]>([]);
  const [historySettings, setHistorySettings] = useState<Record<string, unknown>>({ maxContextMessages: 20, storeHistory: true });
  const [importedFolders, setImportedFolders] = useState<FolderConfig[]>([]);
  const [vaultPath, setVaultPath] = useState<string>("");
  const [notes, setNotes] = useState<Note[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [hasCheckedKey, setHasCheckedKey] = useState(false);

  useEffect(() => {
    let isMounted = true;
    if (!electronAPI) {
      setHasCheckedKey(true);
      return;
    }

    const loadStartupData = async () => {
      try {
        const [
          loadedMemories, profile, loadedDashboardSettings, folders, vaultData,
          loadedHistory, loadedHistorySettings, loadedNotes, loadedTasks, loadedContacts
        ] = await Promise.all([
          electronAPI.loadMemories().catch(() => []),
          electronAPI.loadUserProfile().catch(() => ({})),
          electronAPI.loadDashboardSettings().catch(() => null),
          electronAPI.loadImportedFolders().catch(() => []),
          electronAPI.initializeVault().catch(() => null),
          electronAPI.loadHistory().catch(() => []),
          electronAPI.loadHistorySettings().catch(() => null),
          electronAPI.loadNotes().catch(() => []),
          electronAPI.loadTasks().catch(() => []),
          electronAPI.loadContacts().catch(() => [])
        ]);

        if (!isMounted) return;

        if (Array.isArray(loadedMemories)) setMemories(loadedMemories);
        if (profile && Object.keys(profile).length > 0) setUserProfile(profile);
        if (loadedDashboardSettings) setDashboardSettings(loadedDashboardSettings);
        if (Array.isArray(folders)) setImportedFolders(folders);
        if (vaultData?.vaultBase) setVaultPath(vaultData.vaultBase);
        if (Array.isArray(loadedHistory)) setHistory(loadedHistory);
        if (loadedHistorySettings) setHistorySettings(loadedHistorySettings);
        if (Array.isArray(loadedNotes)) setNotes(loadedNotes);
        if (Array.isArray(loadedTasks)) setTasks(loadedTasks);
        if (Array.isArray(loadedContacts)) setContacts(loadedContacts);
      } catch (error) {
        logger.error("Error loading data:", error);
      }
    };

    const verifyApiKey = async () => {
      try {
        const key = await electronAPI.getGeminiToken();
        if (isMounted) setHasCheckedKey(true); // Always set true to finish load
      } catch {
        if (isMounted) setHasCheckedKey(true);
      }
    };

    loadStartupData();
    verifyApiKey();

    const fallback = window.setTimeout(() => { if (isMounted) setHasCheckedKey(true); }, 2000);
    return () => { isMounted = false; window.clearTimeout(fallback); };
  }, []);

  const handleUpdateProfile = async (field: string, value: string) => {
    const updated = { ...userProfile, [field]: value };
    setUserProfile(updated);
    await electronAPI.saveUserProfile(updated);
  };

  const handleUpdateDashboardSettings = async (settings: DashboardSettings) => {
    setDashboardSettings(settings);
    await electronAPI.saveDashboardSettings(settings);
  };

  const handleAddMemory = async (input: string) => {
    if (!input.trim()) return;
    const newMemo = { id: Date.now().toString(), content: input.trim(), category: "personal", timestamp: Date.now() };
    const updated = [newMemo, ...memories];
    setMemories(updated);
    await electronAPI.saveMemories(updated);
  };

  const handleDeleteMemory = async (id: string) => {
    const updated = memories.filter((m) => m.id !== id);
    setMemories(updated);
    await electronAPI.saveMemories(updated);
  };

  const handleMemoriesUpdated = async (updatedMemories: Memory[]) => {
    setMemories(updatedMemories);
    await electronAPI.saveMemories(updatedMemories);
  };

  const handleUpdateHistorySettings = async (settings: Record<string, unknown>) => {
    setHistorySettings(settings);
    await electronAPI.saveHistorySettings(settings);
  };

  const handleClearHistory = async () => {
    if (window.confirm("Are you sure you want to clear all conversation history?")) {
      setHistory([]);
      await electronAPI.clearHistory();
    }
  };

  const handleImportFolder = async () => {
    const result = await electronAPI.pickFolder();
    if (result) {
      const newFolders = [...importedFolders, result];
      setImportedFolders(newFolders);
      electronAPI.saveImportedFolders(newFolders);
    }
  };

  const handleRemoveFolder = (idx: number) => {
    const newFolders = importedFolders.filter((_, i) => i !== idx);
    setImportedFolders(newFolders);
    electronAPI.saveImportedFolders(newFolders);
  };

  const handleOpenFolder = async (folderPath: string) => {
    await electronAPI.openSystemItem({ target: folderPath });
  };

  const handleOpenVaultFolder = async (folderName: string) => {
    await electronAPI.openVaultFolder(folderName);
  };

  const handleSaveNote = async (note: Note) => {
    const updated = notes.find((n) => n.id === note.id) ? notes.map((n) => (n.id === note.id ? note : n)) : [note, ...notes];
    setNotes(updated);
    await electronAPI.saveNotes(updated);
  };

  const handleDeleteNote = async (id: string) => {
    const updated = notes.filter((n) => n.id !== id);
    setNotes(updated);
    await electronAPI.saveNotes(updated);
  };

  const handleSaveTasks = async (updatedTasks: Task[]) => {
    setTasks(updatedTasks);
    await electronAPI.saveTasks(updatedTasks).catch((err: Error) => console.error(err));
    if (electronAPI?.syncTaskReminders) {
      await electronAPI.syncTaskReminders({ tasks: updatedTasks });
    }
  };

  const handleAddContact = async (name: string, phone: string) => {
    const trimmedName = name.trim();
    const trimmedPhone = phone.trim();
    if (!trimmedName || !trimmedPhone) return;
    const existing = contacts.find((c) => c.name.toLowerCase() === trimmedName.toLowerCase());
    const updatedContacts = existing
      ? contacts.map((c) => c.id === existing.id ? { ...c, phone: trimmedPhone, timestamp: Date.now() } : c)
      : [{ id: Date.now().toString(), name: trimmedName, phone: trimmedPhone, timestamp: Date.now() }, ...contacts];
    setContacts(updatedContacts);
    await electronAPI.saveContacts(updatedContacts);
  };

  const handleDeleteContact = async (id: string) => {
    const updatedContacts = contacts.filter((c) => c.id !== id);
    setContacts(updatedContacts);
    await electronAPI.saveContacts(updatedContacts);
  };

  const value = {
    memories, setMemories, handleAddMemory, handleDeleteMemory, handleMemoriesUpdated,
    userProfile, setUserProfile, handleUpdateProfile,
    dashboardSettings, setDashboardSettings, handleUpdateDashboardSettings,
    history, setHistory, historySettings, setHistorySettings, handleUpdateHistorySettings, handleClearHistory,
    importedFolders, setImportedFolders, handleImportFolder, handleRemoveFolder, handleOpenFolder, handleOpenVaultFolder,
    vaultPath, setVaultPath,
    notes, setNotes, handleSaveNote, handleDeleteNote,
    tasks, setTasks, handleSaveTasks,
    contacts, setContacts, handleAddContact, handleDeleteContact,
    hasCheckedKey, setHasCheckedKey
  };

  return <DataContext.Provider value={value}>{children}</DataContext.Provider>;
};

export const useData = () => {
  const context = use(DataContext);
  if (context === undefined) {
    throw new Error("useData must be used within a DataProvider");
  }
  return context;
};

import { GoogleGenAI, Modality, type LiveServerMessage, StartSensitivity, EndSensitivity } from '@google/genai';
import { useState, useRef, useCallback, useEffect } from 'react';

import { tools, getSystemInstruction } from '../config/gemini-config';
import { decode, decodeAudioData, createBlob } from '../lib/audio-helpers';
import { handleToolCalls } from '../lib/gemini-tool-runner';
import { logger } from "../lib/logger";
import { type Message, ConnectionStatus } from '../types';
import { type SystemLog, type UseGeminiLiveProps } from '../types/gemini-live';

// Safely access electronAPI from window
 
// @ts-ignore
const electronAPI = window.electronAPI;

export const useGeminiLive = ({
  onSpeakingChanged,
  onImageGenerated,
  onMemoriesUpdated,
  onContactsUpdated,
  userProfile,
  onDiagramGenerated,
  onVisualizingChanged,
  vaultInfo,
  initialHistory = [],
  historySettings,
  onDashboardUpdated,
  onNotesUpdated,
  onTasksUpdated,
  onYouTubePlay,
  attachedFiles = []
}: UseGeminiLiveProps = {}) => {

  const maxContextMessages = Math.max(1, Number(historySettings?.maxContextMessages ?? 20));

  const [status, setStatus] = useState<ConnectionStatus>(ConnectionStatus.DISCONNECTED);
  const [messages, setMessages] = useState<Message[]>(initialHistory.slice(-maxContextMessages));
  const [currentInput, setCurrentInput] = useState('');
  const [currentOutput, setCurrentOutput] = useState('');
  const [currentThought, setCurrentThought] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const thinkingEnabledRef = useRef(true);
  const [thinkingEnabled, setThinkingEnabled] = useState(true);
  const currentTurnHasThinkingRef = useRef(false); // Track if current turn has received thinking
  const [logs, setLogs] = useState<SystemLog[]>([]);
  
  // Use ref to always get latest attachedFiles value (avoid closure issues)
  const attachedFilesRef = useRef(attachedFiles);
  
  // Update ref whenever attachedFiles prop changes
  useEffect(() => {
    attachedFilesRef.current = attachedFiles;
  }, [attachedFiles]);

  const setThinkingEnabledState = useCallback((enabled: boolean) => {
    setThinkingEnabled(enabled);
    thinkingEnabledRef.current = enabled;
  }, []);

  useEffect(() => {
    setMessages((prev) =>
      prev.length > maxContextMessages ? prev.slice(-maxContextMessages) : prev
    );
  }, [maxContextMessages]);

  // Note: Thinking config is set during session initialization (line 163-166)
  // No reconnection needed - budget is applied at connect time
  // Toggle state is checked via thinkingEnabledRef during runtime

  const addLog = useCallback((type: SystemLog['type'], message: string, details?: unknown) => {
    const newLog: SystemLog = {
      id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      timestamp: Date.now(),
      type,
      message,
      details
    };
    setLogs(prev => [...prev.slice(-99), newLog]); // Keep last 100 logs

    // EXTREME LOGGING FOR DEBUGGING
    const timestamp = new Date().toLocaleTimeString();
    const prefix = `[Theta-DEBUG ${timestamp}]`;
    if (type === 'error') logger.error(`${prefix} ❌ ${message}`, details || '');
    else if (type === 'warning') logger.warn(`${prefix} ⚠️ ${message}`, details || '');
    else if (type === 'tool') logger.log(`%c${prefix} 🛠️ ${message}`, 'color: #00e5ff; font-weight: bold; border-left: 3px solid #00e5ff; padding-left: 5px;', details || '');
    else if (type === 'success') logger.log(`%c${prefix} ✅ ${message}`, 'color: #00ff8f; font-weight: bold;', details || '');
    else logger.log(`${prefix} ℹ️ ${message}`, details || '');
  }, []);


  // Refs for audio processing
  const audioContextInputRef = useRef<AudioContext | null>(null);
  const audioContextOutputRef = useRef<AudioContext | null>(null);
  const outputAnalyserRef = useRef<AnalyserNode | null>(null);
  const inputAnalyserRef = useRef<AnalyserNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionRef = useRef<{
    close: () => void;
    sendRealtimeInput: (params: [{ mimeType: string; data: string }] | { media: { mimeType: string; data: string } }) => void;
    sendClientContent: (params: { turns: { role: string; parts: { text?: string; inlineData?: { mimeType: string; data: string } }[] }[], turnComplete: boolean }) => void;
  } | null>(null);
  const micStreamRef = useRef<MediaStream | null>(null);

  const cleanup = useCallback(async() => {
    logger.log('Cleaning up session and audio...');
    if (micStreamRef.current) {
      micStreamRef.current.getTracks().forEach(track => track.stop());
    }
    if (audioContextInputRef.current && audioContextInputRef.current.state !== 'closed') {
      await audioContextInputRef.current.close();
    }
    if (audioContextOutputRef.current && audioContextOutputRef.current.state !== 'closed') {
      await audioContextOutputRef.current.close();
    }
    if (sessionRef.current) {
      try {
        sessionRef.current.close();
      } catch (e) {
        logger.warn('Error closing session:', e);
      }
    }

    micStreamRef.current = null;
    audioContextInputRef.current = null;
    audioContextOutputRef.current = null;
    sessionRef.current = null;
    nextStartTimeRef.current = 0;
    sourcesRef.current.clear();
    setStatus(ConnectionStatus.DISCONNECTED);
    onSpeakingChanged?.(false);
  }, [onSpeakingChanged]);

  const connect = async () => {
    try {
      setStatus(ConnectionStatus.CONNECTING);
      setError(null);

      // Get API Key securely
      const apiKey = await electronAPI.getGeminiToken();
      if (!apiKey) {
        throw new Error('Could not retrieve API Key');
      }

      // 1. Initialize Audio Contexts
      const inputCtx = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 24000 });

      await inputCtx.resume();
      await outputCtx.resume();

      audioContextInputRef.current = inputCtx;
      audioContextOutputRef.current = outputCtx;

      const outAnalyser = outputCtx.createAnalyser();
      outAnalyser.fftSize = 256;
      outAnalyser.connect(outputCtx.destination);
      outputAnalyserRef.current = outAnalyser;

      const inAnalyser = inputCtx.createAnalyser();
      inAnalyser.fftSize = 256;
      // Note: Don't connect inAnalyser to destination to avoid feedback
      inputAnalyserRef.current = inAnalyser;

      // 2. Get Microphone
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;

      // 3. Initialize AI
      const ai = new GoogleGenAI({ apiKey });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Charon' } },
          },
          realtimeInputConfig: {
            automaticActivityDetection: {
              startOfSpeechSensitivity: StartSensitivity.START_SENSITIVITY_LOW,
              endOfSpeechSensitivity: EndSensitivity.END_SENSITIVITY_HIGH,
              silenceDurationMs: 800,
            }
          },
          thinkingConfig: {
            includeThoughts: true, // Always request thoughts so we can see them if budget > 0
            thinkingBudget: thinkingEnabledRef.current ? 2048 : 0 // 2048 tokens when on, 0 when off
          },
          tools: tools as import("@google/genai").Tool[],
          systemInstruction: getSystemInstruction(
            userProfile,
            vaultInfo,
            initialHistory.slice(-maxContextMessages)
          ),

          outputAudioTranscription: {},
          inputAudioTranscription: {},
        },
        callbacks: {
          onopen: () => {
            addLog('success', 'Theta Live engine connected');
            setStatus(ConnectionStatus.CONNECTED);
            logger.log('%c[Theta-SESSION] Established @ ' + new Date().toLocaleTimeString(), 'background: #004411; color: white; padding: 2px 5px; border-radius: 3px;');

            // Start streaming microphone
            if (inputCtx && stream) {
              try {
                const source = inputCtx.createMediaStreamSource(stream);
                const scriptProcessor = inputCtx.createScriptProcessor(512, 1, 1);

                // Connect mic to input analyser
                source.connect(inputAnalyserRef.current!);

                scriptProcessor.onaudioprocess = (e) => {
                  const inputData = e.inputBuffer.getChannelData(0);
                  const pcmBlob = createBlob(inputData);
                  sessionPromise.then((session) => {
                    session.sendRealtimeInput({ media: pcmBlob });
                  }).catch(err => {
                    // Silent on audio heartbeat unless it's a real crash
                    if (status === ConnectionStatus.CONNECTED) {
                      logger.warn('[Theta-DEBUG] Lost audio heartbeat:', err.message);
                    }
                  });
                };

                source.connect(scriptProcessor);
                scriptProcessor.connect(inputCtx.destination);
                addLog('info', 'Microphone hardware linked to AI session');
              } catch (err) {
                logger.error('[Theta-DEBUG] Audio Source Linking Failed:', err);
                setError('Could not start microphone stream.');
              }
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            // Audio Output & Thoughts
            const modelTurnPart = message.serverContent?.modelTurn?.parts?.[0];

            // Capture Thinking Process from modelTurn if available (text parts usually handle thoughts/transcriptions)
            // But strict text responses should be handled via outputTranscription or regular modelTurn text logic
            // We do NOT want to treat model text as user input.


            // Capture Thinking Process

            const base64Audio = modelTurnPart?.inlineData?.data;
            if (base64Audio && audioContextOutputRef.current) {
              setIsThinking(false);
              onSpeakingChanged?.(true);
              const ctx = audioContextOutputRef.current;
              if (ctx.state === 'suspended') await ctx.resume();

              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);

              try {
                const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
                const source = ctx.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(outputAnalyserRef.current!);

                source.addEventListener('ended', () => {
                  sourcesRef.current.delete(source);
                  if (sourcesRef.current.size === 0) {
                    onSpeakingChanged?.(false);
                  }
                });

                source.start(nextStartTimeRef.current);
                nextStartTimeRef.current += audioBuffer.duration;
                sourcesRef.current.add(source);
              } catch (err) {
                logger.error("Error playing audio chunk:", err);
              }
            }

            // Interruption handling
            if (message.serverContent?.interrupted) {
              logger.log('Model interrupted');
              sourcesRef.current.forEach(s => {
                try { s.stop(); } catch (e) { }
              });
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              onSpeakingChanged?.(false);
              setIsThinking(false);
              setCurrentThought('');
              setCurrentInput('');   // Clear input buffer on interruption
              setCurrentOutput('');  // Clear output buffer on interruption
            }

            // Text Parts (Potential Thoughts or Content)
            const parts = message.serverContent?.modelTurn?.parts;
            if (parts) {
              parts.forEach(part => {
                // Deep Inspection of Thinking Data
                // API implementation: part.thought is a boolean, and if true, part.text is the thought.
                // ONLY show thinking if toggle is enabled (check ref for real-time value)
                if (part.thought && part.text && thinkingEnabledRef.current) {
                  // If this is the first thought of a new turn, clear previous thinking
                  if (!currentTurnHasThinkingRef.current) {
                    setCurrentThought(''); // Clear old thinking
                    currentTurnHasThinkingRef.current = true;
                  }

                  setIsThinking(true);
                  setCurrentThought(prev => {
                    // Avoid duplicate appends if chunks are resent (simple check)
                    if (prev.endsWith(part.text as string)) return prev;
                    return prev + (prev ? " " : "") + part.text;
                  });
                }
              });
            }

            // Transcriptions & Streaming Messages
            if (message.serverContent?.inputTranscription) {
              const text = message.serverContent.inputTranscription.text;
              setCurrentInput(prev => prev + text);
            }

            if (message.serverContent?.outputTranscription) {
              const text = message.serverContent.outputTranscription.text;
              setCurrentOutput(prev => {
                const newOutput = prev + text;
                // Update the last assistant message in real-time if it exists, otherwise create it
                setMessages(msgs => {
                  const lastMsg = msgs[msgs.length - 1];
                  if (lastMsg && lastMsg.role === 'assistant' && lastMsg.isStreaming) {
                    const updated = [...msgs];
                    updated[updated.length - 1] = { ...lastMsg, text: newOutput };
                      return updated.length > maxContextMessages
                        ? updated.slice(-maxContextMessages)
                        : updated;
                  } else {
                      const appended = [...msgs, {
                      id: `streaming-a-${Date.now()}`,
                      role: 'assistant' as const,
                      text: newOutput,
                      timestamp: Date.now(),
                      isStreaming: true
                      }];
                      return appended.length > maxContextMessages
                        ? appended.slice(-maxContextMessages)
                        : appended;
                  }
                });
                return newOutput;
              });
            }

            // Turn complete - Commit streaming messages
            if (message.serverContent?.turnComplete) {
              // Capture the thought but DON'T clear it yet - let it stay visible for user to scroll
              const finalThought = currentThought;
              setIsThinking(false); // Mark thinking as complete, but keep the text
              currentTurnHasThinkingRef.current = false; // Reset for next turn
              // Note: currentThought will be cleared when next turn's thinking arrives

              // Handle User Input Finalization
              setCurrentInput(val => {
                const cleanVal = val?.trim();
                // Only add user message if we valid text that DOESN'T look like a system echo
                if (cleanVal) {
                  setMessages(msgs => {
                    // Deduplication: Check if a similar user message was added recently
                    const exists = msgs.some(m => m.role === 'user' && m.text.trim() === cleanVal && (Date.now() - m.timestamp < 5000));
                    if (exists) return msgs;

                    const newUserMsg = {
                      id: `${Date.now()}-u`,
                      role: 'user' as const,
                      text: cleanVal,
                      timestamp: Date.now()
                    };

                    // Check if the last message is the Assistant's (streaming or just finished)
                    // If so, we want to insert the User message BEFORE it, because the User spoke first.
                    const lastMsg = msgs[msgs.length - 1];
                    if (lastMsg && lastMsg.role === 'assistant') {
                      const newMsgs = [...msgs];
                      newMsgs.splice(newMsgs.length - 1, 0, newUserMsg);
                      return newMsgs.length > maxContextMessages
                        ? newMsgs.slice(-maxContextMessages)
                        : newMsgs;
                    }

                    const appended = [...msgs, newUserMsg];
                    return appended.length > maxContextMessages
                      ? appended.slice(-maxContextMessages)
                      : appended;
                  });
                }
                return ''; // Clear input buffer
              });

              // Handle Assistant Output Finalization
              setCurrentOutput(val => {
                setMessages(msgs => {
                  const lastMsg = msgs[msgs.length - 1];
                  if (lastMsg && lastMsg.role === 'assistant' && lastMsg.isStreaming) {
                    const updated = [...msgs];
                    updated[updated.length - 1] = {
                      ...lastMsg,
                      id: `${Date.now()}-a`,
                      isStreaming: false,
                      thought: finalThought || undefined // Attach the thought!
                    };
                    return updated.length > maxContextMessages
                      ? updated.slice(-maxContextMessages)
                      : updated;
                  }
                  return msgs;
                });
                return ''; // Clear output buffer
              });
            }

            // Tool Calls Handling
            if (message.toolCall) {
              const calls = message.toolCall.functionCalls;
              if (calls) {
                await sessionPromise.then(async session => {
                 await handleToolCalls(calls, session, {
                    addLog,
                    onVisualizingChanged,
                    onImageGenerated,
                    onDiagramGenerated,
                    onMemoriesUpdated,
                    onContactsUpdated,
                    onDashboardUpdated,
                    onNotesUpdated,
                    onTasksUpdated,
                    electronAPI,
                    apiKey,
                    onYouTubePlay,
                    getAttachedFiles: () => attachedFilesRef.current,
                    cleanup
                  });
                });
              }
            }

          },
          onerror: async (e) => {
            logger.error('%c[Theta-CRITICAL] WebSocker Error:', 'background: #440000; color: white;', e);
            addLog('error', 'Session error occurred', e);
            setError('Connection lost. Please try again.');
            await cleanup();

          },
          onclose:async (e) => {
            logger.warn(`%c[Theta-DISCONNECT] Closed | Code: ${e.code} | Reason: ${e.reason || 'No specific reason'}`, 'color: orange; font-weight: bold;');
            addLog('info', `Session closed (Code: ${e.code})`);
            await cleanup();

          }
        }
      });

      sessionRef.current = await sessionPromise as unknown as NonNullable<typeof sessionRef.current>;
    } catch (err: unknown) {
      const error = err as Error;
      logger.error('Connection failed during setup:', error);
      setError(error.message || 'Failed to initialize session');
      setStatus(ConnectionStatus.ERROR);
     await cleanup();
    }
  };

  useEffect(() => {
    async function cleanupEffect() {
      await cleanup();
    }
    cleanupEffect().then(()=>{
      logger.log('cleanupEffect completed');
    }).catch((error)=>{
      logger.error('cleanupEffect failed:', error);
    })
  }, [cleanup]);

  const sendVideoFrame = useCallback((base64Data: string) => {
    if (sessionRef.current && status === ConnectionStatus.CONNECTED) {
      try {
        sessionRef.current.sendRealtimeInput({
          media: {
            data: base64Data,
            mimeType: 'image/jpeg'
          }
        });
      } catch (err) {
        logger.error('Error sending video frame:', err);
      }
    }
  }, [status]);

  const sendTextMessage = useCallback((text: string, silent: boolean = false) => {
    if (sessionRef.current && status === ConnectionStatus.CONNECTED) {
      try {
        // Keep local context bounded before each outbound turn.
        setMessages((prev) => (prev.length > maxContextMessages ? prev.slice(-maxContextMessages) : prev));

        const shouldForceDeepReasoning = /financial|finance|business|market|strategy|strategic|investment|revenue|profit|pricing|roi|growth|startup/i.test(
          text
        );

        let outboundText = text;
        if (shouldForceDeepReasoning) {
          if (!thinkingEnabledRef.current) {
            setThinkingEnabledState(true);
            addLog('info', 'Deep Reasoning auto-enabled for business/financial query');
          }
          outboundText = `[DEEP_REASONING_REQUIRED] ${text}`;
        }

        // Correct method for @google/genai LiveSession is sendClientContent
        // and it requires a turns-based structure
        sessionRef.current.sendClientContent({
          turns: [{
            role: 'user',
            parts: [{ text: outboundText }]
          }],
          turnComplete: true
        });

        if (silent) {
          addLog('info', `Sent background system command`);
        } else {
          // Add to messages immediately for responsiveness
          setMessages(prev => {
            const appended = [...prev, {
            id: `${Date.now()}-u`,
            role: 'user' as const,
            text,
            timestamp: Date.now()
          }];
            return appended.length > maxContextMessages
              ? appended.slice(-maxContextMessages)
              : appended;
          });
          addLog('info', `User sent message: ${text.substring(0, 30)}${text.length > 30 ? '...' : ''}`);
        }
      } catch (err) {


        logger.error('Error sending text message:', err);
      }
    }
  }, [status, addLog, maxContextMessages, setThinkingEnabledState]);

  const sendMultimodalMessage = useCallback((text: string, attachments: { name: string, data: string, mimeType: string }[]) => {
    if (sessionRef.current && status === ConnectionStatus.CONNECTED) {
      try {
        // Keep local context bounded before each outbound turn.
        setMessages((prev) => (prev.length > maxContextMessages ? prev.slice(-maxContextMessages) : prev));

        const fileNames = attachments.map(f => f.name).join(', ');
        addLog('info', `Sending ${attachments.length} files to Theta: ${fileNames}`);

        // Build parts array: FILES FIRST, then TEXT PROMPT
        // This ensures AI sees the file data before the question (proper context)
        const parts: { text?: string; inlineData?: { mimeType: string; data: string } }[] = [];

        // Add all file attachments as inlineData parts
        attachments.forEach(file => {
          const rawData = file.data.includes(',') ? file.data.split(',')[1] : file.data;
          parts.push({
            inlineData: {
              mimeType: file.mimeType,
              data: rawData
            }
          });
          addLog('tool', `📎 Prepared ${file.name} (${file.mimeType})`, { 
            sizeKB: `${Math.round(rawData.length / 1024)} KB` 
          });
        });

        // Add text prompt AFTER files (so AI analyzes files in context of the prompt)
        const finalPrompt = text?.trim() 
          ? text 
          : `I've attached ${attachments.length} file(s) (${fileNames}). Please analyze them carefully and tell me what you find. Be specific and accurate.`;
        
        parts.push({
          text: finalPrompt
        });

        // Send as a SINGLE turn with all parts together
        sessionRef.current.sendClientContent({
          turns: [{
            role: 'user',
            parts
          }],
          turnComplete: true
        });

        // UI Update
        const displayText = text || `[Attached ${attachments.length} files: ${fileNames}]`;
        setMessages(prev => {
          const appended = [...prev, {
          id: `${Date.now()}-u`,
          role: 'user' as const,
          text: displayText,
          timestamp: Date.now()
        }];

          return appended.length > maxContextMessages
            ? appended.slice(-maxContextMessages)
            : appended;
        });

        addLog('success', `✓ Multimodal message sent: ${attachments.length} files + prompt`);
      } catch (err: unknown) {
        const error = err as Error;
        logger.error('Multimodal transmission failed:', error);
        addLog('error', `Transmission Error: ${error.message}`);
      }
    } else {
      addLog('warning', 'Connection unavailable. Establish session before sending files.');
    }
  }, [status, addLog, maxContextMessages]);

  // Track which files have already been pushed to the context to avoid duplicates
  const prevAttachedFilesRef = useRef<Set<string>>(new Set());

  // AUTO-UPLOAD ATTACHMENTS: 
  // Watch for new files and push them to the model context immediately.
  // This solves the issue where "Add File" items were not visible to the Vision model.
  useEffect(() => {
    // If not connected, just reset the tracker so we send them when we do connect
    if (status !== ConnectionStatus.CONNECTED) {
      prevAttachedFilesRef.current.clear();
      return;
    }

    // Identify files that haven't been sent to the AI yet
    const newFiles = attachedFiles.filter(f => !prevAttachedFilesRef.current.has(f.name));

    if (newFiles.length > 0 && sessionRef.current) {
      addLog('info', `🔄 Auto-syncing ${newFiles.length} new attachments to AI context...`);

      const parts: { text?: string; inlineData?: { mimeType: string; data: string } }[] = [];

      newFiles.forEach(file => {
        // Extract raw base64 (remove data:image/png;base64, prefix if present)
        const rawData = file.data.includes(',') ? file.data.split(',')[1] : file.data;
        
        parts.push({
          inlineData: {
            mimeType: file.mimeType,
            data: rawData
          }
        });
        
        // Mark as sent
        prevAttachedFilesRef.current.add(file.name);
      });

      // Add a system note so the AI knows these are context files, not necessarily a prompt to answer immediately
      parts.push({
        text: `[SYSTEM_DATA_LOAD] User has attached these ${newFiles.length} file(s) for context. Analyze them silently. Wait for user's voice command or question about them.`
      });

      try {
        sessionRef.current.sendClientContent({
          turns: [{
            role: 'user',
            parts
          }],
          turnComplete: true
        });
        addLog('success', `✓ ${newFiles.length} Files uploaded to AI Vision Context`);
      } catch (err: unknown) {
        const error = err as Error;
        logger.error('Auto-upload failed:', error);
      }
    }
    
    // Cleanup: If a file was removed from the UI, remove it from our "sent" set
    // so if it's added again, we re-send it.
    const currentFileNames = new Set(attachedFiles.map(f => f.name));
    prevAttachedFilesRef.current.forEach(name => {
      if (!currentFileNames.has(name)) {
        prevAttachedFilesRef.current.delete(name);
      }
    });

  }, [attachedFiles, status, addLog]);

  return {
    connect,
    disconnect: cleanup,
    status,
    messages,
    currentInput,
    currentOutput,
    error,
    analyser: outputAnalyserRef.current,
    micAnalyser: inputAnalyserRef.current,
    sendVideoFrame,
    sendTextMessage,
    sendMultimodalMessage,
    currentThought,
    isThinking,
    thinkingEnabled,
    setThinkingEnabledState,
    addLog,
    logs
  };
};

